            updateDOM: () => {
                document.querySelectorAll('[data-i18n]').forEach(el => {
                    const key = el.getAttribute('data-i18n');
                    if(key) el.innerText = App.I18n.t(key);
                });
                document.querySelectorAll('[data-i18n-ph]').forEach(el => {
                    const key = el.getAttribute('data-i18n-ph');
                    if(key) el.placeholder = App.I18n.t(key);
                });
            },
            fetch: () => {
                 // We still try to fetch from sheet for dynamic updates, but defaults handle the load
                 fetch(`${API_URL}?action=getTranslations`)
                    .then(r => r.json())
                    .then(res => {
                         if(res.status === 'success') {
                             App.State.translations = res.data;
                             App.I18n.updateDOM();
                         }
                    }).catch(() => {});
            }
        },

		UI: {
            // --- 1. NOTIFICATIONS & MODALS ---

            toast: (msg, type = 'info') => { 
                const c = document.getElementById('toast-container');
                if (!c) { 
                    const con = document.createElement('div');
                    con.id = 'toast-container';
                    con.style.cssText = 'position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:11000;width:90%;max-width:350px;pointer-events:none;';
                    document.body.appendChild(con);
                    return App.UI.toast(msg, type); 
                }
                const t = document.createElement('div');
                t.className = `toast align-items-center text-bg-${type === 'danger' ? 'danger' : (type === 'success' ? 'success' : 'dark')} border-0 show mb-2 shadow-lg rounded-pill`;
                t.style.pointerEvents = 'auto';
                const icon = type === 'success' ? '<i class="bi bi-check-circle-fill me-2"></i>' : (type === 'danger' ? '<i class="bi bi-exclamation-triangle-fill me-2"></i>' : '<i class="bi bi-info-circle-fill me-2"></i>');
                t.innerHTML = `<div class="d-flex"><div class="toast-body d-flex align-items-center fs-6 py-3 px-4">${icon} ${msg}</div><button type="button" class="btn-close btn-close-white me-3 m-auto" data-bs-dismiss="toast"></button></div>`;
                c.appendChild(t);
                if (navigator.vibrate) navigator.vibrate(type === 'danger' ? [50,50,50] : 20);
                setTimeout(() => { t.remove(); }, 3500);
            },

            confirm: (msg, title = "Confirmation", onYes) => {
                const m = document.getElementById('universalModal');
                if(!m) return confirm(msg) ? onYes() : null;
                const bsM = new bootstrap.Modal(m, {backdrop: 'static'});
                document.getElementById('u-icon').className = "bi bi-question-circle-fill fs-1 text-warning";
                document.getElementById('u-title').innerText = title;
                document.getElementById('u-msg').innerText = msg;
                document.getElementById('u-input-group').classList.add('d-none');
                document.getElementById('u-btn-cancel').classList.remove('d-none');
                const btn = document.getElementById('u-btn-confirm');
                btn.innerText = "Oui, continuer";
                btn.className = "btn btn-warning text-dark rounded-pill py-2 fw-bold shadow-sm";
                btn.onclick = () => { if (onYes) onYes(); bsM.hide(); };
                bsM.show();
            },

            alert: (msg, title = "Info") => {
                const m = document.getElementById('universalModal');
                if(!m) return alert(msg);
                const bsM = new bootstrap.Modal(m);
                document.getElementById('u-icon').className = "bi bi-info-circle-fill fs-1 text-info";
                document.getElementById('u-title').innerText = title;
                document.getElementById('u-msg').innerText = msg;
                document.getElementById('u-input-group').classList.add('d-none');
                document.getElementById('u-btn-cancel').classList.add('d-none');
                const btn = document.getElementById('u-btn-confirm');
                btn.innerText = "OK";
                btn.className = "btn btn-primary rounded-pill py-2 fw-bold shadow-sm";
                btn.onclick = () => bsM.hide();
                bsM.show();
            },

            prompt: (title, msg, onValue) => {
                const m = document.getElementById('universalModal');
                if(!m) { const v = prompt(msg); if(v) onValue(v); return; }
                const bsM = new bootstrap.Modal(m, {backdrop: 'static'});
                document.getElementById('u-icon').className = "bi bi-shield-lock-fill fs-1 text-dark";
                document.getElementById('u-title').innerText = title;
                document.getElementById('u-msg').innerText = msg;
                const inputDiv = document.getElementById('u-input-group');
                const input = document.getElementById('u-input');
                inputDiv.classList.remove('d-none');
                input.value = '';
                document.getElementById('u-btn-cancel').classList.remove('d-none');
                const btn = document.getElementById('u-btn-confirm');
                btn.innerText = "Valider";
                btn.className = "btn btn-dark rounded-pill py-2 fw-bold shadow-sm";
                btn.onclick = () => { if (input.value && onValue) onValue(input.value); bsM.hide(); };
                input.onkeyup = (e) => { if (e.key === 'Enter') btn.click(); };
                bsM.show();
                setTimeout(() => input.focus(), 500); 
            },

            // --- 2. FORMATTERS & PARSERS ---

            price: (val) => (parseFloat(val) || 0).toFixed(2) + " DH",

            text: (obj) => {
                const l = App.State.lang || 'fr';
                return obj ? (obj[l] || obj['fr'] || "") : "";
            },

            parseImg: (raw) => {
                if (!raw || raw === "[]") return IMG_FALLBACK;
                try { 
                    if (typeof raw === 'string' && raw.startsWith('[')) {
                        const arr = JSON.parse(raw); 
                        return (Array.isArray(arr) && arr.length > 0) ? arr[0] : IMG_FALLBACK; 
                    }
                    return raw; 
                } catch(e) { return raw || IMG_FALLBACK; }
            },

            // --- 3. RENDERERS (This was the missing part!) ---

            renderCard: (item) => {
                const isOut = parseInt(item.stock) <= 0;
                const isBest = item.is_best_seller === "TRUE" || item.is_best_seller === true;
                const safeId = String(item.id).replace(/'/g, "\\'"); 

                return `
                <div class="col-6 col-md-4 col-lg-3">
                    <div class="product-card ${isOut ? 'opacity-75' : ''}" onclick="App.QuickView.open('${safeId}')">
                        ${isBest ? '<span class="badge bg-warning text-dark position-absolute m-2 shadow-sm" style="z-index:5; font-size:10px;">TOP VENTE 🔥</span>' : ''}

                        <div class="img-box">
                            <img src="${item.image}" onload="App.UI.removeWhite(this)" onerror="this.src='${IMG_FALLBACK}'"/>
                        </div>

                        <div class="p-3">
                            <div class="product-title">${App.UI.text(item.title)}</div>

                            <div class="d-flex justify-content-between align-items-center mt-2">
                                <div class="text-primary fw-bold">${App.UI.price(item.price_MAD)}</div>

                                <button class="btn btn-sm btn-light rounded-circle border shadow-sm" 
                                        style="width:32px; height:32px; display:flex; align-items:center; justify-content:center; z-index:2;"
                                        ${isOut ? 'disabled' : ''}
                                        onclick="event.stopPropagation(); App.Cart.add('${safeId}', this)">
                                    <i class="bi bi-plus-lg"></i>
                                </button>
                            </div>
                        </div>
                    </div>
                </div>`;
            },

            showLoginPrompt: () => {
                if(document.getElementById('login-prompt-toast')) return;
                const toast = document.createElement('div');
                toast.id = 'login-prompt-toast';
                toast.style.cssText = "position:fixed; bottom:100px; left:50%; transform:translateX(-50%); background:#6c5ce7; color:#fff; padding:15px 25px; border-radius:25px; z-index:9999; width:90%; max-width:350px; box-shadow:0 15px 35px rgba(108, 92, 231, 0.3); text-align:center;";
                toast.innerHTML = `
                    <div class="small fw-bold mb-2">Sauvegardez vos points et vos favoris ! 🔒</div>
                    <button class="btn btn-sm btn-light rounded-pill fw-bold w-100 mb-2" onclick="App.Router.go('profile'); this.parentElement.remove();">SE CONNECTER</button>
                    <div class="x-small opacity-75 cursor-pointer" onclick="localStorage.setItem('hide_login_prompt', 'true'); this.parentElement.remove();">Plus tard</div>
                `;
                document.body.appendChild(toast);
            },

            // --- 4. ANIMATIONS & HELPERS ---

            removeWhite: (img) => { if (img) img.style.opacity = 1; },

            showSkeletons: (cid, count = 4) => {
                const root = document.getElementById(cid); if (!root) return;
                let h = '';
                for (let i = 0; i < count; i++) {
                    h += `<div class="col-6 col-md-4 col-lg-3"><div class="skeleton-card" style="height:250px; background:#fff; padding:15px; border-radius:16px; border:1px solid #eee; margin-bottom:15px;"><div class="skeleton" style="height:140px; width:100%; margin-bottom:15px; border-radius:12px;"></div><div class="skeleton" style="height:15px; width:80%; margin-bottom:10px; border-radius:4px;"></div><div class="skeleton" style="height:20px; width:40%; border-radius:4px;"></div></div></div>`;
                }
                root.innerHTML = h;
            },

            showSearchSuggestions: (q) => { 
                const resultsBox = document.getElementById('search-suggestions');
                if (!resultsBox) return;
                if (q.length < 2) { resultsBox.style.display = 'none'; return; }
                const terms = q.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").split(/\s+/).filter(t => t);
                const matches = App.State.catalog.filter(p => {
                    const blob = p._searchBlob || "";
                    return terms.every(term => {
                        if (blob.includes(term)) return true;
                        const blobWords = blob.split(' ');
                        return blobWords.some(word => App.Utils.isSimilar(word, term));
                    });
                }).slice(0, 6);

                if (matches.length > 0) {
                    resultsBox.innerHTML = matches.map(m => `
                        <div class="suggestion-item" onclick="App.QuickView.open('${m.id}'); document.getElementById('search-suggestions').style.display='none';">
                            <img src="${m.image}" class="suggestion-img" onerror="this.src='${IMG_FALLBACK}'"/>
                            <div style="flex:1; min-width:0;">
                                <div class="small fw-bold text-dark text-truncate">${App.UI.text(m.title)}</div>
                                <div class="d-flex align-items-center justify-content-between mt-1">
                                    <span class="text-muted x-small">${m.category}</span>
                                    <span class="text-primary fw-bold small">${App.UI.price(m.price_MAD)}</span>
                                </div>
                            </div>
                            <i class="bi bi-chevron-right text-muted small"></i>
                        </div>
                    `).join('');
                    if(matches.length >= 5) {
                        resultsBox.innerHTML += `<div class="p-2 text-center bg-light cursor-pointer" onclick="document.getElementById('search-suggestions').style.display='none'"><small class="fw-bold text-primary">Voir tous les résultats</small></div>`;
                    }
                    resultsBox.style.display = 'block';
                } else { resultsBox.style.display = 'none'; }
            },

            flyToCart: (imgEl) => { 
                if(!imgEl) return;
                const cartBtn = document.querySelector('.bi-bag-fill');
                if(!cartBtn) return;
                const fly = imgEl.cloneNode();
                const rect = imgEl.getBoundingClientRect();
                fly.classList.add('flying-img');
                fly.style.cssText = `pointer-events:none; position:fixed; z-index:9999; transition:all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius:50%; left:${rect.left}px; top:${rect.top}px; width:${rect.width}px; height:${rect.height}px;`;
                document.body.appendChild(fly);
                const cartRect = cartBtn.getBoundingClientRect();
                setTimeout(() => {
                    fly.style.left = cartRect.left + 'px';
                    fly.style.top = cartRect.top + 'px';
                    fly.style.width = '20px';
                    fly.style.height = '20px';
                    fly.style.opacity = '0';
                }, 50);
                setTimeout(() => fly.remove(), 850);
            },

            unlockScroll: () => {
                setTimeout(() => {
                    document.body.style.overflow = '';
                    document.body.style.paddingRight = '';
                    document.body.classList.remove('modal-open');
                    const bd = document.querySelector('.modal-backdrop');
                    if (bd) bd.remove();
                }, 300);
            },

            showLoader: () => {
                let l = document.getElementById('global-loader');
                if (!l) {
                    l = document.createElement('div');
                    l.id = 'global-loader';
                    l.style.cssText = "position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: var(--bg-body); z-index: 9999; display: flex; flex-direction: column; justify-content: center; align-items: center; transition: opacity 0.5s;";
                    document.body.appendChild(l);
                }
                l.innerHTML = `<div class='spinner-border text-primary' role='status' style='width: 3rem; height: 3rem; border-width: 4px;'></div><div class='mt-2 fw-bold text-muted'>Chargement...</div>`;
                l.style.display = 'flex';
                l.style.opacity = '1';
            },

            hideLoader: () => {
                const l = document.getElementById('global-loader');
                if(l) { l.style.opacity = '0'; setTimeout(() => l.remove(), 500); }
            }
        },

		Profile: {
            // --- ADDRESS MANAGEMENT ---
            toggleMode: (mode) => {
                const input = document.getElementById('addr-street');
                const btn = document.getElementById('btn-gps-action');
                if(mode === 'gps') {
                    input.value = ''; input.placeholder = App.I18n.t('ph_street_gps') || "GPS Location..."; input.readOnly = true; 
                    if(btn) btn.classList.remove('d-none');
                } else {
                    input.placeholder = App.I18n.t('ph_street_manual') || "Street Name"; input.readOnly = false; 
                    if(btn) btn.classList.add('d-none');
                }
            },

            openAddressModal: (addrType = 'Home') => {
                const modalEl = document.getElementById('addressModal');
                const modal = bootstrap.Modal.getOrCreateInstance(modalEl);

                // 1. Set Type Radio
                if(addrType.toLowerCase() === 'office') document.getElementById('type-office').checked = true;
                else document.getElementById('type-home').checked = true;

                // 2. Clear Fields
                ['addr-name', 'addr-gps', 'addr-street', 'addr-zip'].forEach(id => {
                    const el = document.getElementById(id);
                    if(el) el.value = '';
                });
                document.getElementById('addr-city').value = 'Casablanca'; 

                // 3. Pre-fill if exists
                const existing = (App.State.addresses && App.State.addresses[addrType.toLowerCase()]) ? App.State.addresses[addrType.toLowerCase()] : null;

                if (existing) {
                    document.getElementById('addr-name').value = existing.name || '';
                    document.getElementById('addr-street').value = existing.street || '';
                    document.getElementById('addr-city').value = existing.city || '';
                    document.getElementById('addr-zip').value = existing.zip || '';

                    if(existing.gps && document.getElementById('addr-gps')) {
                         document.getElementById('addr-gps').value = existing.gps;
                         // Auto-switch to GPS mode visually
                         document.getElementById('mode-gps').checked = true; // Make sure you have this ID in HTML if using toggle logic
                    }
                }
                // Trigger correct mode UI
                const isGps = (existing && existing.gps);
                App.Profile.toggleMode(isGps ? 'gps' : 'manual');

                modal.show();
            },

            parseGPS: (val) => {
                if (val.includes(',') && !val.includes('http')) {
                    const link = `http://googleusercontent.com/maps.google.com/maps?q=${val.trim()}`;
                    const gpsInput = document.getElementById('addr-gps');
                    if(gpsInput) gpsInput.value = link;
                }
            },

            getLocation: (btn) => {
                if (!navigator.geolocation) return App.UI.toast(App.I18n.t('err_geo_not_supported'), 'danger');
                const originalHtml = btn.innerHTML;
                btn.disabled = true;
                btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';

                navigator.geolocation.getCurrentPosition((position) => {
                    const lat = position.coords.latitude; const long = position.coords.longitude;
                    const mapLink = `http://googleusercontent.com/maps.google.com/maps?q=${lat},${long}`;

                    const streetInput = document.getElementById('addr-street');
                    if(streetInput) streetInput.value = mapLink;

                    const gpsInput = document.getElementById('addr-gps');
                    if(gpsInput) gpsInput.value = mapLink;

                    btn.disabled = false; btn.innerHTML = originalHtml; 
                    btn.classList.replace('btn-outline-secondary', 'btn-success'); 
                    App.UI.toast(App.I18n.t('msg_location_found'), "success");
                }, (error) => {
                    console.error("Geo Error:", error); 
                    btn.disabled = false; btn.innerHTML = originalHtml; 
                    App.UI.toast(App.I18n.t('err_geo_failed'), 'danger');
                }, { enableHighAccuracy: true, timeout: 10000 });
            },

            saveAddress: () => {
                if (!App.State.user) return App.UI.toast(App.I18n.t('err_login_first'), 'danger');

                const btn = document.getElementById('save-addr-btn');
                const oldText = btn.innerText;
                btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> Saving...';

                const typeInput = document.querySelector('input[name="addrType"]:checked');
                const type = typeInput ? typeInput.value : 'Home';

                const addrData = {
                    name: document.getElementById('addr-name').value.trim(),
                    street: document.getElementById('addr-street').value.trim(),
                    city: document.getElementById('addr-city').value.trim(),
                    zip: document.getElementById('addr-zip').value.trim(),
                    gps: document.getElementById('addr-gps') ? document.getElementById('addr-gps').value.trim() : "",
                    full: `${document.getElementById('addr-street').value}, ${document.getElementById('addr-city').value}`
                };

                if(!addrData.street && !addrData.gps) {
                     btn.disabled = false; btn.innerText = oldText;
                     return App.UI.toast(App.I18n.t('msg_enter_address'), 'warning');
                }

                fetch(API_URL, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: 'updateAddress',
                        data: {
                            userId: App.State.user.id,
                            authToken: App.State.user.authToken,
                            type: type,
                            addressJson: JSON.stringify(addrData)
                        }
                    })
                })
                .then(r => r.json())
                .then(res => {
                    btn.disabled = false; btn.innerText = oldText;
                    if (res.status === 'success') {
                        if (!App.State.addresses) App.State.addresses = {};
                        App.State.addresses[type.toLowerCase()] = addrData;

                        App.Profile.renderAddresses();
                        bootstrap.Modal.getInstance(document.getElementById('addressModal')).hide();
                        App.UI.toast(App.I18n.t('msg_addr_saved'), 'success');
                    } else {
                        App.UI.toast("Error: " + res.message, 'danger');
                    }
                })
                .catch(() => {
                    btn.disabled = false; btn.innerText = oldText;
                    App.UI.toast("Connection Error", 'danger');
                });
            },

            renderAddresses: () => { 
                const c = document.getElementById('address-list-grid'); if(!c) return; c.innerHTML = ''; 
                const a = App.State.addresses || {}; 
                let html = ''; 
                if(a.home) html += App.Profile.createAddrCard('Home', a.home); 
                if(a.office) html += App.Profile.createAddrCard('Office', a.office); 
                if(!html) html = `<div class="col-12 text-center text-muted py-3">${App.I18n.t('addr_empty')}</div>`; 
                c.innerHTML = html; 
                App.I18n.updateDOM(); 
            },

            createAddrCard: (type, data) => { 
                const display = (typeof data === 'string') ? data : (data.full || `${data.street} ${data.apt || ''}<br>${data.city}`); 
                const labelKey = type === 'Home' ? 'lbl_home' : 'lbl_office'; 
                const icon = (data.street && data.street.includes('http')) ? `<i class="bi bi-pin-map-fill text-danger"></i> ${App.I18n.t('lbl_gps_location')}` : '<i class="bi bi-geo-alt-fill"></i> ' + (data.name || type);
                return `<div class="col-md-6"><div class="address-card"><span class="address-tag" data-i18n="${labelKey}">${App.I18n.t(labelKey)}</span><h6 class="fw-bold mb-3">${icon}</h6><p class="small text-muted mb-3 text-truncate">${display}</p><button class="btn btn-sm btn-outline-dark rounded-pill px-3" onclick="App.Profile.openAddressModal('${type}')" data-i18n="btn_edit">Edit</button></div></div>`; 
            },

            // --- SETTINGS ---
            saveSettings: () => { 
                if(!App.State.user) return;
                const btn = document.getElementById('save-settings-btn'); 
                if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } 

                const n = document.getElementById('setting-name').value; 
                const e = document.getElementById('setting-email').value; 
                const p = document.getElementById('setting-phone').value; 

                fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateUser', data: { userId: App.State.user.id, authToken: App.State.user.authToken, name: n, email: e, phone: p } })})
                .then(r=>r.json()).then(res=>{ 
                    if(res.status==='success') {
                        App.State.user.name = n; // Update local state
                        App.Utils.save('se_user', App.State.user);
                        App.UI.toast(App.I18n.t('msg_settings_saved'), 'success'); 
                    }
                    if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_changes'); } 
                }); 
            },

            updatePointsUI: () => { 
                const el = document.querySelector('.profile-info .sub-link'); 
                if(el && App.State.user) { 
                    el.innerHTML = `<span class="points-badge"><i class="bi bi-star-fill me-1"></i> ${App.State.user.points} ${App.I18n.t('lbl_pts')}</span>`; 
                } 
            },

            // --- ORDER HISTORY ---
            renderHistory: () => { 
                const list = document.getElementById('order-history-list'); if(!list) return; 
                if(!App.State.history || App.State.history.length === 0) { list.innerHTML = `<p class="text-muted small py-2 text-center">${App.I18n.t('history_empty')}</p>`; return; } 
                list.innerHTML = ''; 

                App.State.history.forEach(o => { 
                    const displayTotal = App.Utils.fmt(parseFloat(o.total)) || "0.00 DH"; 
                    let thumbsHtml = ''; 

                    try { 
                        const items = JSON.parse(o.items); 
                        if(items && items.length) { 
                            thumbsHtml = items.slice(0, 3).map(item => { 
                                var img = IMG_FALLBACK; 
                                // Match item ID to catalog to get image
                                if (typeof item === 'object' && item.id) {
                                    const prod = App.State.catalog.find(p => String(p.id) === String(item.id));
                                    if (prod) img = prod.image;
                                } 
                                return `<img src="${App.Utils.optimizeImg(img, 'w100-h100-c')}" class="order-thumb-img"/>`; 
                            }).join(''); 
                        } 
                    } catch(e) { console.error("History Render Error", e); } 

                    const statusKey = 'status_' + o.status.toLowerCase().replace(/\s+/g, '_');
                    const displayStatus = App.I18n.t(statusKey) === statusKey ? o.status : App.I18n.t(statusKey);
                    const statusClass = (o.status === 'Completed' || o.status === 'Sent' || o.status === 'Delivered') ? 'status-pill-completed' : 'status-pill-processing'; 

                    list.innerHTML += `<div class="order-card-modern"><div class="d-flex justify-content-between mb-3"><span class="fw-bold text-dark">#${o.id}</span><span class="text-muted small">${new Date(o.date).toLocaleDateString()}</span></div><div class="order-thumbs d-flex gap-2 mb-3">${thumbsHtml}</div><div class="d-flex justify-content-between align-items-center mb-2"><span class="text-muted">${App.I18n.t('lbl_status')}</span><span class="${statusClass}">${displayStatus}</span></div><div class="d-flex justify-content-between align-items-center mb-3"><span class="text-muted">${App.I18n.t('lbl_total')}</span><span class="fw-bold fs-5">${displayTotal}</span></div><div class="d-flex gap-2"><button class="btn btn-primary flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_track')}</button><button class="btn btn-light flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_details')}</button><button class="btn btn-outline-primary flex-grow-1 rounded-pill" onclick="App.Cart.reorder('${o.items.replace(/"/g, '&quot;')}')"><i class="bi bi-arrow-repeat"></i> ${App.I18n.t('btn_reorder')}</button></div></div>`; 
                }); 
            },

            showOrderDetail: (id) => { 
                const o = App.State.history.find(x => x.id === id); 
                if(!o) return; 

                let itemsHtml = `<p class="text-muted">${App.I18n.t('msg_no_details')}</p>`;
                try { 
                    const items = JSON.parse(o.items); 
                    if(items && items.length) { 
                        itemsHtml = `<div class="bg-light p-3 rounded mb-3">` + items.map(i => { 
                            let title = "", qty = 1, img = IMG_FALLBACK, unitPrice = 0, pid = null; 
                            if (typeof i === 'object') { 
                                qty = i.qty; 
                                title = App.Utils.getLocalizedText(i.title); 
                                const pObj = App.State.catalog.find(c => String(c.id) === String(i.id));
                                img = (pObj ? pObj.image : i.image) || IMG_FALLBACK; 
                                unitPrice = i.p || i.price;
                                pid = i.id; 
                            } else { title = String(i); } 

                            const subtotal = unitPrice * qty; 
                            const displayPrice = unitPrice > 0 ? App.Utils.fmt(subtotal) : ''; 
                            const reviewBtn = (o.status === 'Completed' && pid) ? `<button class="btn btn-link btn-sm text-decoration-none p-0 ms-2" onclick="App.UI.openReviewModal('${pid}')"><small>★ ${App.I18n.t('btn_write_review')}</small></button>` : ''; 

                            return `<div class="order-detail-row"><img src="${App.Utils.optimizeImg(img)}" class="od-img"/><div><div class="fw-bold small">${qty}x ${title}</div><div class="text-primary small fw-bold">${displayPrice} ${reviewBtn}</div></div></div>`; 
                        }).join('') + `</div>`; 
                    } 
                } catch(e) {} 

                let totalVal = parseFloat(o.total) || 0; 
                const statuses = ['Pending', 'Preparing', 'On the Way', 'Delivered']; 
                let currentStep = statuses.indexOf(o.status); 
                if(o.status === 'Completed') currentStep = 3; 
                if(currentStep === -1) currentStep = 0; 

                const timelineHtml = `<div class="timeline">` + statuses.map((s, idx) => { 
                    const isActive = idx <= currentStep ? 'active' : ''; 
                    const statusKey = 'status_' + s.toLowerCase().replace(/\s+/g,'_'); 
                    return `<div class="timeline-item ${isActive}"><span class="small ${isActive ? 'fw-bold text-success' : 'text-muted'}">${App.I18n.t(statusKey) || s}</span></div>`; 
                }).join('') + `</div>`; 

                let actionButtons = `<button class="btn btn-outline-dark w-100 rounded-pill mt-4" data-bs-dismiss="modal">${App.I18n.t('btn_close')}</button>`;

                if (o.status === 'Pending') {
                    actionButtons = `<div class="d-flex gap-2 mt-4"><button class="btn btn-outline-dark flex-grow-1 rounded-pill" data-bs-dismiss="modal">${App.I18n.t('btn_close')}</button><button id="btn-cancel-order" class="btn btn-danger flex-grow-1 rounded-pill fw-bold" onclick="App.Profile.cancelOrder('${o.id}')">${App.I18n.t('btn_cancel_order') || "Cancel Order"}</button></div>`;
                }

                const mainStatusKey = 'status_' + o.status.toLowerCase().replace(/\s+/g,'_');
                const mainStatusLabel = App.I18n.t(mainStatusKey) === mainStatusKey ? o.status : App.I18n.t(mainStatusKey);

                const html = `<div class="p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="m-0 fw-bold">#${o.id}</h5><span class="badge bg-primary">${mainStatusLabel}</span></div><h6 class="small fw-bold text-muted mb-2 text-uppercase">${App.I18n.t('lbl_timeline')}</h6>${timelineHtml}${itemsHtml}<div class="d-flex justify-content-between fw-bold border-top pt-3"><span>${App.I18n.t('total_caps')}</span><span class="text-primary">${App.Utils.fmt(totalVal)}</span></div>${actionButtons}</div>`; 

                document.getElementById('order-detail-body').innerHTML = html; 
                new bootstrap.Modal(document.getElementById('orderDetailModal')).show(); 
            },

            // --- CANCEL ORDER (ADDED) ---
            cancelOrder: (oid) => {
                App.UI.confirm(App.I18n.t('msg_confirm_cancel') || "Cancel this order?", "", () => {
                    const btn = document.getElementById('btn-cancel-order');
                    if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_cancelling') || "Cancelling..."; }

                    fetch(API_URL, {
                        method: 'POST',
                        body: JSON.stringify({
                            action: 'cancelOrder',
                            data: { userId: App.State.user.id, authToken: App.State.user.authToken, orderId: oid }
                        })
                    })
                    .then(r => r.json())
                    .then(res => {
                        if(res.status === 'success') {
                            App.UI.toast(App.I18n.t('msg_order_cancelled') || "Order Cancelled", "success");
                            bootstrap.Modal.getInstance(document.getElementById('orderDetailModal')).hide();

                            // Update local history status
                            const order = App.State.history.find(o => o.id === oid);
                            if(order) order.status = "Cancelled";
                            App.Profile.renderHistory(); 
                        } else {
                            App.UI.toast(res.message, 'danger');
                            if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_cancel_order') || "Cancel Order"; }
                        }
                    })
                    .catch(() => {
                         App.UI.toast(App.I18n.t('err_conn_failed') || "Connection Failed", 'danger');
                         if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_cancel_order') || "Cancel Order"; }
                    });
                });
            }
        },

        Home: {
            render: () => { 
                const recent = document.getElementById('recent-grid');
                if(recent && App.State.catalog && App.State.catalog.length > 0) {
                    recent.innerHTML = App.State.catalog.slice(0, 8).map(i => App.UI.renderCard(i)).join('');
                }
                App.Home.renderCategories();
                App.Home.initCategoryAutoScroll();
            },
            renderCategories: () => {
                const inner = document.getElementById('cat-scroll-inner');
                if(!inner) return;

                // Icons configuration (Static map, but list is Dynamic)
                const iconMap = { 
                    "E-liquids": "bi-droplet-fill", "Premium E-liquids": "bi-droplet-half", 
                    "Nicotine Salts": "bi-capsule", "Disposables": "bi-ev-station-fill", 
                    "WAKA Puffs": "bi-wind", "VOZOL Puffs": "bi-cloud-haze2-fill", 
                    "Cartridges": "bi-plugin", "Nicotine Pouches": "bi-archive-fill", 
                    "Hardware": "bi-cpu-fill", "Batteries": "bi-battery-charging", 
                    "Atomizers": "bi-gear-wide-connected", "DIY": "bi-beaker", 
                    "Accessories": "bi-usb-c-fill", "Coils": "bi-reception-4", "CBD": "bi-leaf-fill" 
                };

                // Use the Dynamic List we extracted in Catalog.processData
                // If App.State.categories is empty (first load), fallback to keys of iconMap
                const catsToRender = (App.State.categories && App.State.categories.length > 0) 
                    ? App.State.categories 
                    : Object.keys(iconMap);

                inner.innerHTML = catsToRender.map(c => `
                    <div class="cat-item" onclick="App.Catalog.search('${c}'); App.Router.go('catalog')">
                        <div class="cat-icon shadow-sm">
                            <i class="bi ${iconMap[c] || 'bi-tag-fill'}"></i>
                        </div>
                        <div class="small fw-bold mt-2 text-center" style="font-size:10px; white-space: normal; line-height: 1.1;">
                            ${c}
                        </div>
                    </div>`).join('');
            },
            initCategoryAutoScroll: () => {
                const s = document.getElementById('home-cat-slider'); 
                if(!s || s.dataset.scrolling === "true") return;
                s.dataset.scrolling = "true";
                setInterval(() => { s.scrollLeft += 1; if(s.scrollLeft >= s.scrollWidth / 2) s.scrollLeft = 0; }, 30);
            }
        },

        Catalog: {
            // --- STATE VARIABLES ---
            currentPriceSort: 'default', // 'default', 'low', 'high'

            // --- INITIALIZATION ---
            init: (onReady) => {
                App.UI.showSkeletons('product-grid-root', 8);

                // 1. Version Check
                fetch(`${API_URL}?action=getCatalogVersion`)
                    .then(r => r.json())
                    .then(res => {
                        const cloudVer = String(res.version);
                        const localVer = localStorage.getItem('se_catalog_ver');
                        const cachedData = localStorage.getItem('se_catalog_data');

                        // 2. Validate Cache Integrity
                        let valid = false;
                        if (cloudVer === localVer && cachedData && cachedData.length > 50) {
                            try {
                                const p = JSON.parse(cachedData);
                                // MUST have items AND valid IDs to be considered safe
                                if (p.length > 0 && p[0].id) valid = true;
                            } catch(e) {}
                        }

                        if (valid) {
                            console.log("⚡ Loading Catalog from Cache");
                            App.Catalog.processData(JSON.parse(cachedData), onReady);
                        } else {
                            console.log("🔄 Downloading fresh CSV...");
                            App.Catalog.downloadCSV(cloudVer, onReady);
                        }
                    })
                    .catch(e => {
                        console.log("Offline/Error", e);
                        // Offline Fallback: Try to load whatever we have
                        const c = localStorage.getItem('se_catalog_data');
                        if (c) App.Catalog.processData(JSON.parse(c), onReady);
                        else App.Catalog.downloadCSV(null, onReady);
                    });
            },

            // --- DATA LOADING ---
            downloadCSV: (version, onReady) => {
                const url = CSV_URL + "&t=" + Date.now();
                Papa.parse(url, {
                    download: true, header: true, skipEmptyLines: true,
                    complete: (res) => {
                        // --- SMART MAPPING LOGIC ---
                        const getVal = (row, possibleKeys) => {
                            for (const key of possibleKeys) {
                                const foundKey = Object.keys(row).find(k => k.trim().toLowerCase() === key.toLowerCase());
                                if (foundKey) return String(row[foundKey]).trim();
                            }
                            return "";
                        };

                        const processed = res.data.map((r, i) => {
                            // 1. FIND ID (Checks: ID, id, Code, Ref)
                            const id = getVal(r, ['ID', 'id', 'Code', 'Ref', 'SKU']);
                            if (!id || id === "undefined" || id === "") return null;

                            // 2. FIND TITLE
                            const tEn = getVal(r, ['Title_EN', 'Title', 'Name', 'Product Name']);
                            const tFr = getVal(r, ['Title_FR', 'Title_EN', 'Title']); 
                            const tAr = getVal(r, ['Title_AR', 'Arabic']);

                            // 3. FIND PRICE & STOCK
                            const price = parseFloat(getVal(r, ['Price_MAD', 'Price', 'Prix', 'MSRP'])) || 0;
                            const stockRaw = getVal(r, ['Stock', 'Qty', 'Quantity']);
                            const stock = isNaN(parseInt(stockRaw)) ? (stockRaw.toLowerCase().includes('out') ? 0 : 10) : parseInt(stockRaw);

                            // 4. FIND OTHERS
                            const cat = getVal(r, ['Category', 'Cat', 'Collection']) || "Uncategorized";
                            const img = App.UI.parseImg(getVal(r, ['Image_URL', 'Image', 'Img', 'Photo']));
                            const tags = getVal(r, ['Tags', 'Keywords']);
                            const variants = getVal(r, ['Variant_Name', 'Variants', 'Options']);

                            // Create Search Blob
                            const blob = `${tEn} ${tFr} ${cat} ${tags} ${variants} ${id}`.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

                            return {
                                id: id, 
                                rowIndex: i, 
                                category: cat,
                                title: { en: tEn, fr: tFr, ar: tAr },
                                desc: { en: getVal(r,['Desc_EN']), fr: getVal(r,['Desc_FR']), ar: getVal(r,['Desc_AR']) },
                                price_MAD: price,
                                stock: stock,
                                image: img,
                                variant_name: variants,
                                is_best_seller: tags.toLowerCase().includes('best'),
                                _searchBlob: blob
                            };
                        }).filter(p => p !== null); // Remove bad rows

                        // Validate Data Count (>5 items) to prevent saving "Rate Limit" HTML pages
                        if (processed.length > 5) {
                            try {
                                localStorage.setItem('se_catalog_data', JSON.stringify(processed));
                                localStorage.setItem('se_catalog_ver', String(version));
                                console.log(`✅ Saved ${processed.length} items`);
                            } catch(e) { console.log("Cache Full"); }
                            App.Catalog.processData(processed, onReady);
                        } else {
                            console.warn("⚠️ CSV Downloaded but found < 5 valid products (Rate Limit?). Using fallback.");
                            App.Catalog.tryFallback(onReady);
                        }
                    },
                    error: () => App.Catalog.tryFallback(onReady)
                });
            },

            tryFallback: (onReady) => {
                const c = localStorage.getItem('se_catalog_data');
                if(c) {
                    try {
                        const p = JSON.parse(c);
                        if(p.length > 0) {
                            App.UI.toast("Mode hors ligne (Cache)", "warning");
                            App.Catalog.processData(p, onReady);
                            return;
                        }
                    } catch(e){}
                }
                App.UI.toast("Impossible de charger le catalogue", "danger");
                if(onReady) onReady();
            },

            processData: (data, onReady) => {
                if (!data || data.length === 0) return;

                // Extract Categories
                const foundCategories = [...new Set(data.map(p => p.category))].filter(c => c && c !== "Uncategorized");
                App.State.categories = foundCategories.sort();

                // Sort Products (Default: Stock > Category > Index)
                data.sort((a, b) => {
                    const stockA = a.stock > 0 ? 1 : 0;
                    const stockB = b.stock > 0 ? 1 : 0;
                    if (stockA !== stockB) return stockB - stockA; // In stock first

                    let idxA = App.State.categories.indexOf(a.category);
                    let idxB = App.State.categories.indexOf(b.category);
                    if (idxA === -1) idxA = 999; if (idxB === -1) idxB = 999;
                    if (idxA !== idxB) return idxA - idxB;

                    return a.rowIndex - b.rowIndex;
                });

                App.State.catalog = data;
                App.State.filtered = [...App.State.catalog];

                if (App.Home.render) App.Home.render();
                if (App.Catalog.render) { 
                    App.Catalog.render(true); 
                    App.Catalog.initInfiniteScroll(); 
                }

                // Check URL for shared ID
                const urlParams = new URLSearchParams(window.location.search);
                const sharedId = urlParams.get('id');
                if (sharedId) setTimeout(() => { if (App.QuickView) App.QuickView.open(sharedId); }, 800);

                if (onReady) onReady();
            },

            // --- UI & FILTERING ---

            cyclePriceSort: (btn) => {
                const icon = document.getElementById('price-sort-icon');

                // Cycle: default -> low -> high -> default
                if (App.Catalog.currentPriceSort === 'default') {
                    App.Catalog.currentPriceSort = 'low';
                    btn.classList.add('border-primary', 'bg-primary-subtle');
                    icon.className = "bi bi-arrow-up text-primary fw-bold";
                    App.UI.toast("Prix: Croissant 📈");
                } 
                else if (App.Catalog.currentPriceSort === 'low') {
                    App.Catalog.currentPriceSort = 'high';
                    btn.classList.add('border-primary', 'bg-primary-subtle');
                    icon.className = "bi bi-arrow-down text-primary fw-bold";
                    App.UI.toast("Prix: Décroissant 📉");
                } 
                else {
                    App.Catalog.currentPriceSort = 'default';
                    btn.classList.remove('border-primary', 'bg-primary-subtle');
                    icon.className = "bi bi-arrow-down-up text-muted";
                    App.UI.toast("Tri par défaut");
                }
                App.Catalog.applySort();
            },

            applySort: () => {
                const sortMode = App.Catalog.currentPriceSort;

                if (sortMode === 'default') {
                    // Re-run search to apply default order (Stock > Category)
                    const input = document.getElementById('catalog-search-input');
                    if(input) App.Catalog.search(input.value); 
                    return; 
                }

                App.State.filtered.sort((a, b) => {
                    const pa = parseFloat(a.price_MAD) || 0;
                    const pb = parseFloat(b.price_MAD) || 0;
                    return sortMode === 'low' ? pa - pb : pb - pa;
                });
                App.Catalog.render(true);
            },

            search: (q) => {
                const terms = q.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").split(/\s+/).filter(t => t);
                const stockFilter = document.getElementById('stock-filter-select') ? document.getElementById('stock-filter-select').value : 'all';

                App.State.filtered = App.State.catalog.filter(item => {
                    const blob = item._searchBlob || "";
                    const matchText = terms.every(term => {
                        if (blob.includes(term)) return true;
                        const blobWords = blob.split(' ');
                        return blobWords.some(word => App.Utils.isSimilar(word, term));
                    });
                    let matchStock = true;
                    if (stockFilter === 'in') matchStock = item.stock > 0;
                    else if (stockFilter === 'out') matchStock = item.stock <= 0;
                    return matchText && matchStock;
                });

                // Apply Price Sort if active
                if(App.Catalog.currentPriceSort !== 'default') {
                    App.Catalog.applySort();
                } else {
                    App.Catalog.render(true);
                }
            },

            clearFilters: () => { 
                const input = document.getElementById('catalog-search-input');
                const select = document.getElementById('stock-filter-select');
                if(input) input.value = ''; 
                if(select) select.value = 'all';

                // Reset Price Sort UI
                App.Catalog.currentPriceSort = 'default';
                const btn = document.getElementById('btn-price-sort');
                const icon = document.getElementById('price-sort-icon');
                if(btn) btn.classList.remove('border-primary', 'bg-primary-subtle');
                if(icon) icon.className = "bi bi-arrow-down-up text-muted";

                App.State.filtered = [...App.State.catalog]; 
                App.Catalog.render(true); 
                App.UI.toast("Filtres réinitialisés");
            },

            render: (reset = false) => {
                const root = document.getElementById('product-grid-root'); if(!root) return;
                if(reset) { root.innerHTML = ''; App.State.visibleCount = 12; }
                const batch = App.State.filtered.slice(0, App.State.visibleCount);

                root.innerHTML = batch.length 
                    ? batch.map(i => App.UI.renderCard(i)).join('') 
                    : '<div class="text-center py-5 w-100 opacity-50">Aucun produit trouvé</div>';

                const countEl = document.getElementById('catalog-count');
                if(countEl) countEl.innerText = App.State.filtered.length;
            },

            renderNextBatch: () => {
                 const nextBatch = App.State.filtered.slice(App.State.visibleCount, App.State.visibleCount + 12);
                 if(nextBatch.length) { 
                     App.State.visibleCount += 12; 
                     document.getElementById('product-grid-root').insertAdjacentHTML('beforeend', nextBatch.map(i => App.UI.renderCard(i)).join('')); 
                 }
            },

            initInfiniteScroll: () => {
                const s = document.getElementById('scroll-sentinel'); if(!s) return;
                const observer = new IntersectionObserver((entries) => { 
                    if(entries[0].isIntersecting && App.State.filtered.length > App.State.visibleCount) {
                        App.Catalog.renderNextBatch(); 
                    }
                }, { threshold: 0.1 });
                observer.observe(s);
            },

            setView: (m) => { 
                const grid = document.getElementById('product-grid-root');
                if(grid) grid.className = m === 'grid' ? 'row gy-3' : 'row gy-2 list-view'; 
                const btnGrid = document.getElementById('view-grid');
                const btnList = document.getElementById('view-list');
                if(btnGrid && btnList) {
                    if(m === 'grid') { btnGrid.classList.add('active'); btnList.classList.remove('active'); }
                    else { btnList.classList.add('active'); btnGrid.classList.remove('active'); }
                }
            },

            handleSearch: (input) => {
                const val = input.value;
                const clearBtn = document.getElementById('search-clear-btn');
                if(clearBtn) clearBtn.style.display = val.length > 0 ? 'block' : 'none';
                App.Catalog.search(val);
                App.UI.showSearchSuggestions(val);
            },

            clearSearch: () => {
                const input = document.getElementById('catalog-search-input');
                const clearBtn = document.getElementById('search-clear-btn');
                const suggestions = document.getElementById('search-suggestions');
                if(input) input.value = '';
                if(clearBtn) clearBtn.style.display = 'none';
                if(suggestions) suggestions.style.display = 'none';
                App.Catalog.search('');
            },

            // Dummy placeholder for sortPrice (removed in favor of cyclePriceSort, kept for compatibility if called elsewhere)
            sortPrice: (val) => { console.warn("Use cyclePriceSort instead"); }
        },

        Cart: {
            deliveryMode: 'ASAP',
            selectedDate: 'today',
            selectedSlot: '',
            activeCoupon: null,

            // --- MODIFICATION ICI (500 -> 100) ---
            SHIPPING_THRESHOLD: 100, 
            // -------------------------------------

            add: (id, btnElement = null) => { 
                const i = App.State.catalog.find(p => String(p.id) === String(id));
                if(!i) return App.UI.toast("Erreur produit ❌");
                if(i.stock <= 0) return App.UI.toast("Épuisé ❌");

                if(btnElement) {
                    let container = btnElement.closest('.product-card') || btnElement.closest('.qv-content-wrapper') || document.querySelector('#qvModal');
                    let img = container ? container.querySelector('img') : null;
                    if(img) App.UI.flyToCart(img);
                }

                const ex = App.State.cart.find(c => String(c.id) === String(id));
                if(ex) {
                    if(ex.qty >= i.stock) return App.UI.toast(`Max stock (${i.stock})`);
                    ex.qty++;
                } else {
                    App.State.cart.push({
                        ...i, 
                        qty: 1,
                        price_MAD: parseFloat(i.price_MAD) || 0 
                    });
                }

                App.Cart.save(); 
                App.UI.toast("Ajouté 🛒");
				App.UI.unlockScroll();
            },

            remove: (id) => {
                App.UI.confirm("Voulez-vous vraiment retirer cet article ?", "Retirer du panier", () => {
                    App.State.cart = App.State.cart.filter(c => String(c.id) !== String(id));
                    App.Cart.save();
                    App.UI.toast("Article retiré");
                });
            },

            save: () => {
                localStorage.setItem('se_cart', JSON.stringify(App.State.cart));
                localStorage.setItem('se_cart_ts', Date.now().toString());
                App.Cart.render();
                if (App.State.user) App.Sync.toSheet('cart', App.State.cart);
            },

            render: () => {
                const list = document.getElementById('cart-list');
                const empty = document.getElementById('cart-empty-state');
                const badge = document.getElementById('nav-cart-count');

                App.State.cart = App.State.cart.filter(i => i && i.id && !isNaN(parseFloat(i.price_MAD)));

                const count = App.State.cart.reduce((a, b) => a + (parseInt(b.qty) || 1), 0);
                if(badge) {
                    badge.innerText = count;
                    badge.style.display = count > 0 ? 'block' : 'none';
                }

                if (!list) return;

                if (App.State.cart.length === 0) {
                    list.innerHTML = '';
                    if(empty) empty.style.display = 'block';
                    App.Cart.calculateTotals();
                    return;
                }

                if(empty) empty.style.display = 'none';

                list.innerHTML = App.State.cart.map(i => {
                    const isLowStock = i.stock < 5;
                    const price = parseFloat(i.price_MAD) || 0;
                    return `
                    <div class="card border-0 shadow-sm rounded-4 p-3 mb-3 position-relative">
                        <div class="d-flex align-items-center gap-3">
                            <div style="width: 70px; height: 70px; flex-shrink:0; background:#f8f9fa; border-radius:12px; display:flex; align-items:center; justify-content:center;">
                                <img src="${i.image}" style="max-width:100%; max-height:100%; border-radius:8px;" onerror="this.src='${IMG_FALLBACK}'"/>
                            </div>

                            <div class="flex-grow-1">
                                <div class="d-flex justify-content-between align-items-start">
                                    <div>
                                        <div class="fw-bold text-dark" style="font-size:0.95rem; line-height:1.2;">${App.UI.text(i.title)}</div>
                                        ${i.variant_name ? `<div class="x-small text-muted border d-inline-block px-1 rounded mt-1">${i.variant_name}</div>` : ''}
                                        ${isLowStock ? `<div class="x-small text-danger fw-bold mt-1">Plus que ${i.stock} en stock!</div>` : ''}
                                    </div>
                                    <button class="btn btn-sm text-danger p-0 border-0" onclick="App.Cart.remove('${i.id}')"><i class="bi bi-trash"></i></button>
                                </div>

                                <div class="d-flex justify-content-between align-items-end mt-2">
                                    <div class="text-primary fw-bold">${App.UI.price(price)}</div>
                                    <div class="d-flex align-items-center bg-light rounded-pill border">
                                        <button class="btn btn-sm btn-link text-dark text-decoration-none py-0 px-2" onclick="App.Cart.updateQty('${i.id}', -1)">−</button>
                                        <span class="fw-bold px-1" style="font-size:0.9rem;">${i.qty}</span>
                                        <button class="btn btn-sm btn-link text-dark text-decoration-none py-0 px-2" onclick="App.Cart.updateQty('${i.id}', 1)">+</button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>`;
                }).join('');

                App.Cart.calculateTotals();
            },

            updateQty: (id, delta) => {
                const item = App.State.cart.find(c => String(c.id) === String(id));
                if (!item) return;

                const fullItem = App.State.catalog.find(p => String(p.id) === String(id));
                const maxStock = fullItem ? fullItem.stock : 99;

                const newQty = item.qty + delta;

                if (newQty > maxStock) return App.UI.toast(`Stock insuffisant (Max: ${maxStock})`);
                if (newQty <= 0) return App.Cart.remove(id);

                item.qty = newQty;
                App.Cart.save();
            },

            calculateTotals: () => {
                let subtotal = App.State.cart.reduce((a, b) => {
                    const p = parseFloat(b.price_MAD);
                    const q = parseInt(b.qty);
                    return (!isNaN(p) && !isNaN(q)) ? a + (p * q) : a;
                }, 0);

                let totalDiscount = 0;
                let couponDiscount = 0;

                if (App.State.pointsRedeemed && App.State.userPoints > 0) {
                    let pointsVal = (App.State.userPoints / 10) * 5; 
                    totalDiscount += Math.min(pointsVal, subtotal * 0.5);
                }

                if (App.Cart.activeCoupon && App.Cart.activeCoupon.type === 'percent') {
                    couponDiscount = (subtotal * (parseFloat(App.Cart.activeCoupon.val) || 0)) / 100;
                    totalDiscount += couponDiscount;
                }

                if (App.State.exitDiscountApplied) {
                    let remaining = subtotal - totalDiscount;
                    totalDiscount += (remaining * 0.05);
                }

                // --- MODIFICATION ICI (Calcul des frais) ---
                // Si le total est >= 100, frais = 0, sinon 20
                let shipping = (subtotal >= App.Cart.SHIPPING_THRESHOLD) ? 0 : 20;
                if (subtotal === 0) shipping = 0;

                const finalTotal = Math.max(0, subtotal - totalDiscount + shipping);

                const setTxt = (id, val) => { const el=document.getElementById(id); if(el) el.innerText = val; };
                const setDisplay = (id, show) => { const el=document.getElementById(id); if(el) el.style.display = show ? 'flex' : 'none'; };

                setTxt('summary-subtotal', App.UI.price(subtotal));
                setTxt('cart-total', App.UI.price(finalTotal));
                setTxt('summary-shipping', shipping === 0 ? "GRATUITE" : `${shipping} DH`);

                setDisplay('row-discount-coupon', couponDiscount > 0);
                setTxt('val-discount-coupon', `-${couponDiscount.toFixed(2)} DH (${App.Cart.activeCoupon?.code || ''})`);

                setDisplay('row-discount-points', App.State.pointsRedeemed);
                let ptsVal = (totalDiscount - (App.State.exitDiscountApplied ? subtotal*0.05 : 0) - couponDiscount);
                setTxt('val-discount-points', `-${ptsVal.toFixed(2)} DH`);

                // Progress Bar Logic
                const bar = document.getElementById('free-shipping-bar');
                const barTxt = document.getElementById('free-shipping-text');
                if (bar && barTxt) {
                    // Calcul basé sur 100 DH
                    const pct = subtotal > 0 ? Math.min(100, (subtotal / App.Cart.SHIPPING_THRESHOLD) * 100) : 0;
                    bar.style.width = pct + "%";
                    if (pct >= 100) {
                        bar.classList.replace('bg-primary', 'bg-success');
                        barTxt.innerHTML = "🎉 <b>Bravo !</b> Livraison offerte.";
                    } else {
                        bar.classList.replace('bg-success', 'bg-primary');
                        const remaining = (App.Cart.SHIPPING_THRESHOLD - subtotal).toFixed(0);
                        // Texte dynamique
                        barTxt.innerText = `Plus que ${remaining} DH pour la livraison gratuite`;
                    }
                }

                // Update static display text as well just in case
                const thresholdDisp = document.getElementById('shipping-threshold-disp');
                if(thresholdDisp) thresholdDisp.innerText = App.Cart.SHIPPING_THRESHOLD;

                return finalTotal;
            },

            togglePoints: (checked) => {
                if (!App.State.user) { 
                    App.UI.toast("Connectez-vous pour utiliser vos points"); 
                    document.getElementById('use-points-check').checked = false; 
                    return; 
                }
                App.State.pointsRedeemed = checked;
                App.Cart.calculateTotals();
            },

            applyCoupon: () => {
                const code = document.getElementById('coupon-input').value.trim();
                if (!code) return;

                App.UI.toast("Vérification...");

                const currentTotal = App.State.cart.reduce((a, b) => a + (parseFloat(b.price_MAD) * b.qty), 0);

                fetch(API_URL, {
                    method: 'POST',
                    body: JSON.stringify({ 
                        action: "checkCoupon", 
                        code: code, 
                        total: currentTotal 
                    })
                })
                .then(r => r.json())
                .then(res => {
                    if (res.status === 'success') {
                        App.UI.toast(`Code appliqué ! -${res.discount}% 🎉`);
                        App.Cart.activeCoupon = { 
                            code: code.toUpperCase(), 
                            val: parseFloat(res.discount), 
                            type: 'percent' 
                        };
                        App.Cart.calculateTotals();
                    } else {
                        App.UI.toast(res.message || "Code invalide");
                        App.Cart.activeCoupon = null;
                        App.Cart.calculateTotals();
                    }
                })
                .catch(() => App.UI.toast("Erreur réseau"));
            },

            setDeliveryMode: (mode) => {
                App.Cart.deliveryMode = mode;
                document.getElementById('del-opt-asap').classList.toggle('active', mode === 'ASAP');
                document.getElementById('del-opt-sched').classList.toggle('active', mode === 'SCHED');
                document.getElementById('schedule-panel').style.display = mode === 'SCHED' ? 'block' : 'none';
                if(mode === 'SCHED') App.Cart.renderSlots();
            },

            renderSlots: () => {
                const slots = ["10:00 - 12:00", "12:00 - 14:00", "14:00 - 16:00", "16:00 - 18:00", "18:00 - 20:00"];
                const container = document.getElementById('slots-container');
                container.innerHTML = slots.map(s => `
                    <button class="btn btn-sm btn-outline-dark rounded-3" 
                            style="font-size:11px"
                            onclick="App.Cart.selectedSlot='${s}'; document.querySelectorAll('#slots-container button').forEach(b=>b.classList.remove('active')); this.classList.add('active');">
                        ${s}
                    </button>
                `).join('');
            },

            checkout: () => {
                const total = App.Cart.calculateTotals();
                if (total === 0) return App.UI.toast("Panier vide");
                if (total < 100) return App.UI.toast("Minimum de commande: 100 DH");

                const name = document.getElementById('chk-name').value.trim();
                const phone = document.getElementById('chk-phone').value.trim();
                const address = document.getElementById('chk-address').value.trim();

                if (!name || !phone || !address) return App.UI.toast("Veuillez remplir toutes les infos");

                let msg = `*NOUVELLE COMMANDE* 🛒\n`;
                msg += `👤 *Client:* ${name}\n`;
                msg += `📞 *Tél:* ${phone}\n`;
                msg += `📍 *Adresse:* ${address}\n\n`;

                msg += `*ARTICLES:*\n`;
                App.State.cart.forEach(i => {
                    msg += `▫️ ${i.qty}x ${i.title.fr || i.title.en} (${i.price_MAD} DH)\n`;
                    if(i.variant_name) msg += `   └ _${i.variant_name}_\n`;
                });

                msg += `\n💰 *TOTAL:* ${total.toFixed(2)} DH`;

                if(App.Cart.activeCoupon) msg += `\n🏷️ *Code:* ${App.Cart.activeCoupon.code} (-${App.Cart.activeCoupon.val}%)`;
                if(App.State.pointsRedeemed) msg += `\n🌟 *Points:* Utilisés`;

                if (App.Cart.deliveryMode === 'SCHED') {
                    msg += `\n📅 *Livraison:* ${App.Cart.selectedDate} @ ${App.Cart.selectedSlot || 'Non spécifié'}`;
                } else {
                    msg += `\n🚀 *Livraison:* Immédiate (ASAP)`;
                }

                const orderPayload = {
                    action: "placeOrder",
                    data: {
                        userId: App.State.user?.phone || "Guest",
                        name: name, 
                        phone: phone, 
                        address: address,
                        total: total,
                        cart: App.State.cart.map(i => ({id:i.id, qty:i.qty, p:i.price_MAD, title: i.title.fr})), 
                        note: App.Cart.deliveryMode,
                        coupon: App.Cart.activeCoupon ? App.Cart.activeCoupon.code : "",
                        pointsUsed: App.State.pointsRedeemed ? (App.State.userPoints || 0) : 0
                    }
                };

                const btn = document.querySelector('#cart-module .btn-primary');
                const oldTxt = btn.innerHTML;
                btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';

                fetch(API_URL, { method: 'POST', body: JSON.stringify(orderPayload) })
                .then(r => r.json())
                .then(res => {
                    if(res.status === 'success') {
                        confetti({ particleCount: 200, spread: 80 });
                        setTimeout(() => {
                            const waLink = `https://wa.me/212661552233?text=${encodeURIComponent(msg)}`;
                            window.open(waLink, '_blank');

                            App.State.cart = [];
                            App.Cart.activeCoupon = null; 
                            App.Cart.save();
                            App.Router.go('home');
                            btn.disabled = false; btn.innerHTML = oldTxt;
                        }, 1000);
                    } else {
                        App.UI.toast("Erreur: " + res.message);
                        btn.disabled = false; btn.innerHTML = oldTxt;
                    }
                });
            }
        },

        Auth: {
            login: () => {
                const pInput = document.getElementById('login-phone'), pwInput = document.getElementById('login-pass'), lBtn = document.querySelector('#auth-forms-container .btn-primary');
                if (!pInput.value || !pwInput.value) return App.UI.toast("Champs requis");
                const cleanPhone = pInput.value.replace(/\D/g, ""), oldTxt = lBtn.innerHTML;
                lBtn.disabled = true; lBtn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';

                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: "login", phone: cleanPhone, password: pwInput.value.trim() }) })
                .then(r => r.json()).then(res => {
                    if (res.status === 'success') {
                        localStorage.setItem('se_user', JSON.stringify(res.user));
                        App.Auth.restoreCloudData(res.user.phone);
                        App.Auth.restoreSession(res.user);
                        App.UI.toast("Bienvenue 👋");
                    } else { App.UI.toast(res.message || "Erreur"); lBtn.disabled = false; lBtn.innerHTML = oldTxt; }
                }).catch(() => { App.UI.toast("Erreur réseau"); lBtn.disabled = false; lBtn.innerHTML = oldTxt; });
            },
            restoreCloudData: (phone) => {
                fetch(`${API_URL}?action=getUserData&userId=${encodeURIComponent(phone)}`).then(r => r.json()).then(res => {
                    if (res.status === 'success') {
                        const safeParse = (str) => { try { return JSON.parse(str); } catch(e) { return []; } };
                        const performSync = (type, cloudStr, cloudTs) => {
                            const localKey = `se_${type}`, tsKey = `se_${type}_ts`;
                            const localData = JSON.parse(localStorage.getItem(localKey) || "[]"), localTs = parseInt(localStorage.getItem(tsKey) || "0"), cloudTime = parseInt(cloudTs || 0);

                            if (cloudTime > localTs && cloudStr && cloudStr !== "[]") {
                                const items = safeParse(cloudStr);
                                if(items.length > 0) {
                                    if (type === 'viewed') localStorage.setItem(localKey, JSON.stringify(items.map(i => i.id)));
                                    else {
                                        App.State[type] = items.map(i => { const full = App.State.catalog.find(p => p.id === i.id); return full ? { ...full, qty: i.qty || 1 } : null; }).filter(Boolean);
                                        localStorage.setItem(localKey, JSON.stringify(App.State[type]));
                                    }
                                    localStorage.setItem(tsKey, cloudTime.toString());
                                }
                            } else if (localTs > cloudTime && localData.length > 0) {
                                // --- FIX WAS APPLIED HERE ---
                                let pushData = (type === 'viewed') ? localData.map(id => ({id:id})) : App.State[type];
                                App.Sync.toSheet(type, pushData);
                            }
                        };
                        performSync('cart', res.cart, res.cartTime);
                        performSync('wishlist', res.wishlist, res.wishTime);
                        performSync('viewed', res.viewed, res.viewedTime);

                        // Render updates
                        if(App.Cart.render) App.Cart.render(); 
                        if(App.Wishlist.render) App.Wishlist.render(); 
                        if(App.Viewed.render) App.Viewed.render();
                    }
                });
            },
            restoreSession: (u) => {
                if (!u) return;
                App.State.user = u; App.State.userPoints = parseInt(u.points) || 0;

                const nameEl = document.getElementById('dash-name-display');
                if(nameEl) nameEl.innerText = u.name;

                const phoneEl = document.getElementById('dash-phone-display');
                if(phoneEl) phoneEl.innerText = u.phone;

                const ptsEl = document.getElementById('user-points-display');
                if(ptsEl) ptsEl.innerText = App.State.userPoints;

                const cartPts = document.getElementById('cart-points-balance');
                if(cartPts) cartPts.innerText = App.State.userPoints;

                document.getElementById('auth-forms-container').style.display = 'none';
                document.getElementById('user-dashboard').style.display = 'block';

                const role = String(u.role || "").toLowerCase();
                if(document.getElementById('btn-admin-trigger')) document.getElementById('btn-admin-trigger').style.display = (role === 'admin' || role === 'merchant') ? 'block' : 'none';

                App.Auth.fetchUserOrders(u.phone);
            },
            fetchUserOrders: (phone) => {
                // Ensure phone is just digits for API call
                const cleanPhone = String(phone).replace(/\D/g, "");
                fetch(`${API_URL}?action=getUserOrders&phone=${encodeURIComponent(cleanPhone)}`).then(r => r.json()).then(res => {
                    if (res.status === 'success') {
                        App.State.tempOrders = res.orders;
                        document.getElementById('user-orders-count').innerText = res.orders.length;
                        document.getElementById('user-order-history').innerHTML = res.orders.map(o => `
                            <div class="card border-0 shadow-sm mb-2 p-3 rounded-4"><div class="d-flex justify-content-between"><b>#${o.id}</b><span class="badge bg-primary-subtle text-primary">${o.status}</span></div><div class="small text-muted mt-1">${App.UI.price(o.total)} • ${o.date}</div><button class="btn btn-sm btn-outline-primary rounded-pill mt-2" onclick="App.Auth.reorder('${o.id}')">Commander à nouveau</button></div>`).join('');
                    }
                });
            },
            reorder: (id) => {
                const o = App.State.tempOrders.find(x => String(x.id) === String(id)); if (!o) return;
                try { 
                    const items = typeof o.items === 'string' ? JSON.parse(o.items) : o.items; 
                    items.forEach(it => { App.Cart.add(it.id); }); 
                    App.Router.go('cart'); 
                } catch (e) { App.UI.toast("Erreur commande"); }
            },
            logout: () => { localStorage.clear(); location.reload(); },
            register: () => {
                const name = document.getElementById('reg-name').value.trim(), phone = document.getElementById('reg-phone').value.replace(/\D/g, ""), pass = document.getElementById('reg-pass').value.trim();
                if (!name || !phone || !pass) return App.UI.toast("Veuillez remplir tous les champs");
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: "register", data: { name, phone, password: pass, email: document.getElementById('reg-email').value || "", currency: "MAD", lang: App.State.lang } }) }).then(r => r.json()).then(res => {
                    if (res.status === 'success') { App.UI.toast("Compte créé !"); document.getElementById('register-form-box').style.display = 'none'; document.getElementById('login-form-box').style.display = 'block'; document.getElementById('login-phone').value = phone; } else { App.UI.toast(res.message); }
                });
            }
        },

        Admin: {
            login: () => {
                // Beautiful Prompt instead of window.prompt
                App.UI.prompt("Accès Admin", "Veuillez entrer le code PIN marchand:", (pin) => {
                    if(pin === "1234") { 
                        App.State.adminPw = pin; 
                        localStorage.setItem('merchant_pin', pin);
                        App.Admin.fetchOrders();
                        App.Router.go('admin');
                        App.UI.toast("Admin connecté 🔐");
                    } else {
                        App.UI.toast("Code PIN incorrect", "danger");
                    }
                });
            },
            fetchOrders: () => {
                const listRoot = document.getElementById('admin-orders-list'); if (!listRoot) return;
                fetch(`${API_URL}?action=getAdminDashboard&pw=${encodeURIComponent(App.State.adminPw)}`).then(r => r.json()).then(res => {
                    if(res.status === 'success') {
                        App.State.tempOrders = res.orders;
                        App.Admin.renderSalesReport();
                        const ordersHtml = res.orders.map(o => {
                            let statusClass = "bg-warning text-dark"; 
                            const s = String(o.status).toLowerCase();
                            if (s.includes("livré") || s.includes("done")) statusClass = "bg-success text-white";
                            if (s.includes("annul") || s.includes("cancel")) statusClass = "bg-danger text-white";
                            if (s.includes("cours") || s.includes("process")) statusClass = "bg-info text-white";
                            const waPhone = String(o.phone).replace(/\D/g, "");
                            return `<div class="card p-3 mb-2 border-0 shadow-sm rounded-4 bg-white"><div class="d-flex justify-content-between align-items-start mb-2"><div><b class="text-dark">#${o.id}</b><div class="x-small text-muted" style="font-size:10px;">${o.date}</div></div><span class="badge ${statusClass} rounded-pill px-3 py-2" style="font-size:10px;">${o.status.toUpperCase()}</span></div><div class="small fw-bold text-secondary mb-1">${o.name}</div><div class="small text-primary fw-bold mb-3">${App.UI.price(o.total)}</div><div class="d-flex gap-2"><button class="btn btn-sm btn-outline-primary flex-grow-1 rounded-pill fw-bold" style="font-size:10px;" onclick="App.Admin.viewOrderDetail('${o.id}')">DÉTAILS</button><a href="https://wa.me/${waPhone}?text=Bonjour ${o.name}, concernant votre commande #${o.id}..." target="_blank" class="btn btn-sm btn-success rounded-pill px-3"><i class="bi bi-whatsapp"></i></a></div></div>`;
                        }).join('');
                        listRoot.innerHTML = ordersHtml || '<div class="text-center py-5 opacity-50">Aucune commande</div>';
                    }
                });
            },
            viewOrderDetail: (id) => {
                const order = App.State.tempOrders.find(o => String(o.id) === String(id)); if(!order) return;
                let itemsList = []; try { itemsList = typeof order.items === 'string' ? JSON.parse(order.items) : order.items; } catch(e) { itemsList = []; }
                const detailHtml = `<div class="p-4"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="fw-bold m-0">Commande #${order.id}</h5><button class="btn btn-sm btn-outline-dark rounded-pill px-3" onclick="window.print()"><i class="bi bi-printer me-1"></i> IMPRIMER</button></div><div class="mb-3"><label class="x-small fw-bold text-muted">STATUT</label><select class="form-select rounded-pill" onchange="App.Admin.updateStatus('${order.id}', this.value)"><option value="En attente" ${order.status === 'En attente' ? 'selected' : ''}>En attente</option><option value="En cours" ${order.status === 'En cours' ? 'selected' : ''}>En cours</option><option value="Livré" ${order.status === 'Livré' ? 'selected' : ''}>Livré</option><option value="Annulé" ${order.status === 'Annulé' ? 'selected' : ''}>Annulé</option></select></div><div class="bg-light p-3 rounded-4 mb-3 small"><h6 class="fw-bold mb-2 border-bottom pb-1">Articles:</h6>${itemsList.map(it => `<div class="d-flex justify-content-between mb-1"><span>${it.qty}x ${it.title || ('Item ' + it.id)}</span><span>${App.UI.price(it.price || 0)}</span></div>`).join('')}<div class="border-top mt-2 pt-2 fw-bold text-primary text-end">TOTAL: ${App.UI.price(order.total)}</div></div><div class="mb-3 p-3 border rounded-4 small"><div class="fw-bold text-muted">Info Client:</div><div>${order.name}</div><div>${order.phone}</div><div class="text-muted mt-1">${order.address}</div></div><button class="btn btn-dark w-100 rounded-pill py-2" data-bs-dismiss="modal">Fermer</button></div>`;
                document.getElementById('qv-body').innerHTML = detailHtml;
                const modalEl = document.getElementById('qvModal');
                const modal = new bootstrap.Modal(modalEl, { focus: false });
                modal.show();
            },
            updateStatus: (orderId, newStatus) => {
                App.UI.toast("Mise à jour...");
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: "updateOrderStatus", password: App.State.adminPw, data: { orderId: orderId, status: newStatus } }) })
                .then(r => r.json()).then(res => { if(res.status === 'success') { App.UI.toast("Statut mis à jour ✅"); App.Admin.fetchOrders(); } });
            },
            setView: (v) => {
                document.getElementById('admin-orders-view').style.display = v === 'orders' ? 'block' : 'none';
                document.getElementById('admin-catalog-panel').style.display = v === 'catalog' ? 'block' : 'none';
                if (v === 'catalog') App.Admin.renderCatalog();
                if (v === 'orders') { App.Admin.fetchOrders(); App.Admin.renderSalesReport(); }
            },
            renderCatalog: (query = "") => {
                const container = document.getElementById('admin-catalog-items'); if (!container) return;
                const instockOnly = document.getElementById('filter-instock-only')?.checked;
                let items = App.State.catalog.filter(p => (App.UI.text(p.title) + p.id + p.category).toLowerCase().includes(query.toLowerCase().trim()));
                if (instockOnly) items = items.filter(p => parseInt(p.stock) > 0);
                container.innerHTML = items.map(p => {
                    const stockNum = parseInt(p.stock) || 0; const isInStock = stockNum > 0;
                    let lowBadge = (stockNum > 0 && stockNum < 5) ? `<span class="badge bg-danger-subtle text-danger ms-2" style="font-size: 9px;">STOCK FAIBLE (${stockNum})</span>` : '';
                    return `<div class="p-3 border-bottom bg-white"><div class="d-flex align-items-center justify-content-between mb-2"><div class="d-flex align-items-center gap-2 text-truncate"><img src="${p.image}" style="width:40px;height:40px;object-fit:contain;border-radius:8px; border:1px solid #eee;"/><div class="text-truncate"><div class="small fw-bold text-dark text-truncate">${App.UI.text(p.title)} ${lowBadge}</div><div class="x-small text-muted">ID: ${p.id}</div></div></div><div class="form-check form-switch"><input class="form-check-input" type="checkbox" role="switch" ${isInStock ? 'checked' : ''} onchange="App.Admin.toggleStock('${p.id}', this.checked)"></div></div><div class="d-flex gap-2"><div class="input-group input-group-sm shadow-sm" style="width: 140px;"><input type="number" class="form-control rounded-start-pill ps-3" id="price-edit-${p.id}" value="${p.price_MAD}"><span class="input-group-text bg-white border-start-0 pe-3 rounded-end-pill small fw-bold">DH</span></div><button class="btn btn-sm btn-dark rounded-pill px-3 shadow-sm" onclick="App.Admin.updatePrice('${p.id}')" style="font-size: 10px;">SAVE</button></div></div>`;
                }).join('') || '<div class="p-5 text-center opacity-50">Aucun produit</div>';
            },
            toggleStock: (productId, status) => {
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: "toggleStock", password: App.State.adminPw, data: { productId, status } }) })
                .then(r => r.json()).then(res => { if (res.status === 'success') { App.UI.toast(status ? "En stock ✅" : "Epuisé ❌"); const item = App.State.catalog.find(p => p.id === productId); if (item) item.stock = status ? 100 : 0; } });
            },
            updatePrice: (productId) => {
                const priceInput = document.getElementById(`price-edit-${productId}`); if (!priceInput) return;
                const newPrice = parseFloat(priceInput.value);
                App.UI.toast("Mise à jour...");
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: "updatePrice", password: App.State.adminPw, productId: String(productId), price: newPrice }) })
                .then(r => r.json()).then(res => { if (res.status === 'success') { App.UI.toast("Prix sauvegardé ! 💰"); const item = App.State.catalog.find(p => String(p.id) === String(productId)); if (item) item.price_MAD = newPrice; } });
            },
            getDailyReport: () => {
                const orders = App.State.tempOrders || [];
                const today = new Date().toISOString().split('T')[0];
                const todayOrders = orders.filter(o => o.date.startsWith(today));
                const totalSales = todayOrders.reduce((sum, o) => sum + parseFloat(o.total || 0), 0);
                alert(`Rapport du jour (${today}):\n\nCommandes: ${todayOrders.length}\nTotal: ${totalSales.toFixed(2)} DH`);
            },
            renderSalesReport: () => {
                const container = document.getElementById('admin-report-container'); if (!container) return;
                const orders = App.State.tempOrders || [];
                const days = {}; for(let i=0; i<7; i++) { let d = new Date(); d.setDate(d.getDate() - i); days[d.toISOString().split('T')[0]] = 0; }
                orders.forEach(o => { if(!o.date) return; const dateKey = String(o.date).split(' ')[0]; if(days[dateKey] !== undefined) days[dateKey] += parseFloat(o.total || 0); });
                const max = Math.max(...Object.values(days)) || 1;
                const chartHtml = Object.entries(days).reverse().map(([date, val]) => `<div class="d-flex flex-column align-items-center flex-fill"><div class="x-small text-muted mb-1" style="font-size:7px;">${val > 0 ? Math.round(val) : ''}</div><div class="bg-primary rounded-top" style="width:14px; height:${(val/max)*70}px; min-height:2px; transition: height 0.5s ease;"></div><div class="text-muted mt-2" style="font-size:8px;">${date.split('-')[2]}</div></div>`).join('');
                container.innerHTML = `<div class="bg-white p-3 rounded-4 shadow-sm mb-4 border"><h6 class="fw-bold mb-3 x-small text-muted text-uppercase">Chiffre d'affaires (7j)</h6><div class="d-flex align-items-end gap-1 mb-3" style="height:100px; border-bottom:1px solid #eee; padding-bottom:5px;">${chartHtml}</div><div class="d-flex flex-wrap gap-2 pt-2 border-top mt-2"><span class="badge bg-warning text-dark rounded-pill px-2" style="font-size:9px;">● En attente</span><span class="badge bg-info text-white rounded-pill px-2" style="font-size:9px;">● En cours</span><span class="badge bg-success text-white rounded-pill px-2" style="font-size:9px;">● Livré</span></div></div>`;
            }
        },

        QuickView: {
            tempQty: 1,
            currentRating: 5,

            open: (id) => {
                // 1. Sanitize ID
                const targetId = String(id).trim();

                // 2. Check for Catalog
                if (!App.State.catalog || App.State.catalog.length === 0) {
                    App.UI.toast("Catalogue en chargement...", "warning");
                    return;
                }

                // 3. Find Product (Loose match for safety)
                const foundItem = App.State.catalog.find(i => String(i.id).trim() === targetId);

                // 4. Handle Missing
                if (!foundItem) {
                    console.warn(`Product ${targetId} not found.`);
                    App.UI.toast("Produit introuvable", "warning");
                    return;
                }

                // 5. Track History
                if(App.Viewed) App.Viewed.add(targetId);

                // 6. Show Modal
                const modalEl = document.getElementById('qvModal');
                if (!modalEl) return;

                const activeModal = bootstrap.Modal.getInstance(modalEl);
                if (activeModal) {
                    activeModal.hide();
                    setTimeout(() => {
                        App.QuickView.initModal(foundItem); 
                        App.QuickView.fetchReviews(foundItem.id);
                        new bootstrap.Modal(modalEl).show();
                    }, 300);
                } else {
                    App.QuickView.initModal(foundItem);
                    App.QuickView.fetchReviews(foundItem.id);
                    new bootstrap.Modal(modalEl).show();
                }
            },

            initModal: (itemParam) => {
                // SAFETY: Use a different name 'itemParam' to prevent "Identifier already declared" error
                if (!itemParam) return;

                const item = itemParam; // Safe assignment
                App.QuickView.tempQty = 1;

                let localLang = App.State.lang || 'fr';
                const isWishlisted = App.State.wishlist.some(w => String(w.id) === String(item.id));
                const variants = item.variant_name ? item.variant_name.split(',').map(v => v.trim()).filter(v => v !== "") : [];
                const descObj = item.desc || {};
                const descriptionText = descObj[localLang] || descObj['fr'] || descObj['en'] || "Aucune description disponible.";
                const img = item.image || IMG_FALLBACK;

                const modalBody = document.getElementById('qv-body');
                if(!modalBody) return;

                modalBody.innerHTML = `
                    <div class="d-flex gap-2" style="position: absolute; top: 15px; right: 15px; z-index: 2000;">
                        <button class="btn btn-white rounded-circle shadow-sm" onclick="App.Wishlist.toggle('${item.id}')" id="qv-wish-btn" style="width:35px; height:35px; border:none; background:rgba(255,255,255,0.8);">
                            <i class="bi ${isWishlisted ? 'bi-heart-fill text-danger' : 'bi-heart'}"></i>
                        </button>
                        <button class="qv-close-btn position-static" data-bs-dismiss="modal" style="width:35px; height:35px;"><i class="bi bi-x-lg"></i></button>
                    </div>

                    <div id="qv-scroll-container" style="height: 85vh; overflow-y: auto; scrollbar-width: none; background: #fff;">
                        <div class="qv-img-sticky p-4">
                            <img src="${img}" class="img-fluid" id="qv-main-img" onerror="this.src='${IMG_FALLBACK}'"/>
                        </div>

                        <div class="qv-details-content p-4">
                            <h4 class="fw-bold mb-1">${App.UI.text(item.title)}</h4>
                            <p class="text-muted small mb-3">${item.category}</p>

                            ${variants.length > 0 ? `
                            <div class="mb-4">
                                <label class="x-small fw-bold text-muted text-uppercase mb-2" style="font-size:10px; letter-spacing:1px;">Options :</label>
                                <div class="d-flex flex-wrap gap-2">
                                    ${variants.map(v => `<span class="badge rounded-pill border text-dark fw-normal px-3 py-2" style="background:#f8f9fa; border-color:#eee !important; font-size:11px;">${v}</span>`).join('')}
                                </div>
                            </div>` : ''}

                            <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-2">
                                <h6 class="fw-bold m-0">Description</h6>
                                <button class="btn btn-sm bg-white rounded-pill px-3 shadow-sm" id="btn-translate-desc" style="font-size:10px; border:1px solid #eee; font-weight:700;">${localLang.toUpperCase()}</button>
                            </div>

                            <div id="qv-live-desc" class="text-muted small" style="line-height:1.6;">${descriptionText}</div>

                            <div class="mt-4 pt-4 border-top">
                                <h6 class="fw-bold mb-3">Avis Clients <span id="review-count" class="badge bg-light text-dark ms-2">0</span></h6>
                                <div id="review-form-container">
                                    ${App.State.user ? `
                                        <div class="bg-light p-3 rounded-4 mb-3">
                                            <div class="d-flex gap-2 mb-2 text-warning" id="star-rating-selector">
                                                <i class="bi bi-star-fill cursor-pointer" onclick="App.QuickView.setRating(1)"></i>
                                                <i class="bi bi-star-fill cursor-pointer" onclick="App.QuickView.setRating(2)"></i>
                                                <i class="bi bi-star-fill cursor-pointer" onclick="App.QuickView.setRating(3)"></i>
                                                <i class="bi bi-star-fill cursor-pointer" onclick="App.QuickView.setRating(4)"></i>
                                                <i class="bi bi-star-fill cursor-pointer" onclick="App.QuickView.setRating(5)"></i>
                                            </div>
                                            <textarea id="review-comment" class="form-control form-control-sm border-0 shadow-sm mb-2" rows="2" placeholder="Votre avis..."></textarea>
                                            <button class="btn btn-primary btn-sm rounded-pill w-100 fw-bold" onclick="App.QuickView.submitReview('${item.id}')">ENVOYER</button>
                                        </div>` : `
                                        <div class="bg-light p-3 rounded-4 mb-3 text-center"><p class="x-small text-muted mb-0">Connectez-vous pour laisser un avis.</p></div>`
                                    }
                                </div>
                                <div id="reviews-list-root" class="x-small text-muted"></div>
                            </div>
                            <div style="height:100px;"></div>
                        </div>
                    </div>

                    <div class="qv-checkout-bar d-flex flex-column gap-3 shadow-lg">
                        <div class="d-flex align-items-center justify-content-between px-2">
                            <div class="d-flex align-items-center bg-light rounded-pill p-1">
                                <button class="btn btn-sm bg-white rounded-circle shadow-sm border-0" style="width:30px; height:30px;" onclick="App.QuickView.updateQty('${item.id}', -1)">-</button>
                                <span class="px-3 fw-bold" id="qv-qty-display">1</span>
                                <button class="btn btn-sm bg-white rounded-circle shadow-sm border-0" style="width:30px; height:30px;" onclick="App.QuickView.updateQty('${item.id}', 1)">+</button>
                            </div>
                            <div class="text-end">
                                <div class="x-small text-muted">Total</div>
                                <div class="fw-bold text-primary" id="qv-total-price">${App.UI.price(item.price_MAD)}</div>
                            </div>
                        </div>
                        <button class="btn btn-primary rounded-pill w-100 py-3 fw-bold shadow-sm" onclick="App.QuickView.addToCartAndClose('${item.id}', this)">
                            AJOUTER AU PANIER
                        </button>
                    </div>
                `;

                // Translate Logic
                const descBtn = document.getElementById('btn-translate-desc');
                const descContainer = document.getElementById('qv-live-desc');
                if (descBtn && descContainer) {
                    let currentL = localLang;
                    descBtn.onclick = () => {
                        const langs = ['fr', 'en', 'ar'];
                        currentL = langs[(langs.indexOf(currentL) + 1) % 3];
                        const txt = descObj[currentL] || descObj['fr'] || descObj['en'] || "Aucune description.";
                        descContainer.innerHTML = txt;
                        descBtn.innerText = currentL.toUpperCase();
                    };
                }

                App.QuickView.currentRating = 5;
            },

            updateQty: (id, delta) => {
                if (navigator.vibrate) navigator.vibrate(10);
                const item = App.State.catalog.find(i => String(i.id) === String(id));
                if (!item) return;
                App.QuickView.tempQty = Math.max(1, Math.min(15, (App.QuickView.tempQty || 1) + delta));
                const d = document.getElementById('qv-qty-display');
                const p = document.getElementById('qv-total-price');
                if(d) d.innerText = App.QuickView.tempQty;
                if(p) p.innerText = App.UI.price(item.price_MAD * App.QuickView.tempQty);
            },

            addToCartAndClose: (id, btnElement) => {
                if (navigator.vibrate) navigator.vibrate(30);

                // Add to cart
                App.Cart.add(id, btnElement); 

                // Update specific quantity
                const existing = App.State.cart.find(c => String(c.id) === String(id));
                const qtyToAdd = App.QuickView.tempQty || 1;

                if (existing) {
                    // Cart.add adds +1, so we adjust to match tempQty
                    // Logic: existing was (old + 1), we want (old + tempQty)
                    existing.qty = (existing.qty - 1) + qtyToAdd;
                    if(existing.qty < 1) existing.qty = 1;
                } else {
                    const fresh = App.State.cart.find(c => String(c.id) === String(id));
                    if(fresh) fresh.qty = qtyToAdd;
                }
                App.Cart.save();

                // Close
                const modalEl = document.getElementById('qvModal');
                const modalInstance = bootstrap.Modal.getInstance(modalEl);
                if (modalInstance) modalInstance.hide();
                if(App.UI.unlockScroll) App.UI.unlockScroll();
            },

            setRating: (n) => {
                App.QuickView.currentRating = n;
                const stars = document.querySelectorAll('#star-rating-selector i');
                stars.forEach((s, idx) => {
                    s.className = idx < n ? "bi bi-star-fill cursor-pointer" : "bi bi-star cursor-pointer";
                });
            },

            fetchReviews: (id) => {
                const root = document.getElementById('reviews-list-root');
                const countBadge = document.getElementById('review-count');
                if (!root) return;

                root.innerHTML = '<div class="py-2"><span class="spinner-border spinner-border-sm me-2"></span>Chargement...</div>';
                if (countBadge) countBadge.innerText = "0";

                const safeId = String(id).trim();
                fetch(`${API_URL}?action=getReviews&productId=${encodeURIComponent(safeId)}&t=${Date.now()}`)
                .then(r => r.json())
                .then(res => {
                    if (res.status === 'success' && res.reviews && res.reviews.length > 0) {
                        if (countBadge) countBadge.innerText = res.reviews.length;
                        root.innerHTML = res.reviews.map(r => `
                            <div class="mb-3 border-bottom pb-2">
                                <div class="d-flex justify-content-between align-items-center">
                                    <div><b class="text-dark" style="font-size:12px;">${r.name}</b>${r.isVerified ? '<span class="badge bg-success-subtle text-success ms-2" style="font-size:8px;">VÉRIFIÉ</span>' : ''}</div>
                                    <span class="text-warning" style="font-size:10px;">${'★'.repeat(r.rating)}${'☆'.repeat(5 - r.rating)}</span>
                                </div>
                                <div class="mt-1 text-muted" style="font-size:11px;">${r.comment}</div>
                            </div>
                        `).join('');
                    } else {
                        root.innerHTML = "<div class='py-3 opacity-50 small'>Aucun avis pour le moment.</div>";
                    }
                })
                .catch(err => { root.innerHTML = "<div class='py-3 text-danger small'>Erreur.</div>"; });
            },

            submitReview: (productId) => {
                const comment = document.getElementById('review-comment').value;
                if (!comment || comment.trim().length < 3) return App.UI.toast("Commentaire trop court");
                if (!App.State.user) return App.UI.toast("Connectez-vous");

                const data = {
                    action: "addReview",
                    productId: String(productId),
                    phone: App.State.user.phone,
                    name: App.State.user.name,
                    rating: App.QuickView.currentRating,
                    comment: comment
                };

                App.UI.toast("Envoi...");
                fetch(API_URL, { method: 'POST', body: JSON.stringify(data) })
                    .then(r => r.json())
                    .then(res => {
                        if (res.status === 'success') {
                            App.UI.toast("Avis enregistré ! ⭐");
                            App.QuickView.fetchReviews(productId);
                            document.getElementById('review-comment').value = '';
                        }
                    });
            },

            share: (id, title) => {
                if (navigator.vibrate) navigator.vibrate(10);
                const url = `${window.location.protocol}//${window.location.host}${window.location.pathname}?id=${id}`;
                if (navigator.share) navigator.share({ title, url }).catch(() => {});
                else {
                    const el = document.createElement('textarea'); el.value = url; document.body.appendChild(el); el.select(); document.execCommand('copy'); document.body.removeChild(el);
                    App.UI.toast("Lien copié !");
                }
            }
        },
        Wishlist: {
            toggle: (id) => {
                if (navigator.vibrate) navigator.vibrate(15);
                const idx = App.State.wishlist.findIndex(w => String(w.id) === String(id));
                if (idx > -1) { 
                    App.State.wishlist.splice(idx, 1); 
                    App.UI.toast("Retiré 💔"); 
                } 
                else { 
                    const item = App.State.catalog.find(p => String(p.id) === String(id)); 
                    if(item) { 
                        App.State.wishlist.push(item); 
                        App.UI.toast("Ajouté ❤️"); 
                    } 
                }
                App.Wishlist.save();
            },
            remove: (id) => {
                const idx = App.State.wishlist.findIndex(w => String(w.id) === String(id));
                if (idx > -1) { 
                    App.State.wishlist.splice(idx, 1); 
                    App.Wishlist.save(); 
                }
            },
            save: () => {
                localStorage.setItem('se_wishlist', JSON.stringify(App.State.wishlist));
                localStorage.setItem('se_wish_ts', Date.now().toString());
                App.Wishlist.render();
                if (App.State.user) App.Sync.toSheet('wishlist', App.State.wishlist);
            },
            clear: () => { 
                App.UI.confirm("Voulez-vous vider toute votre liste ?", "Vider la liste", () => { 
                    App.State.wishlist = []; 
                    App.Wishlist.save(); 
                }); 
            },
            render: () => {
                const grid = document.getElementById('wishlist-grid'), 
                      empty = document.getElementById('wishlist-empty'), 
                      badge = document.getElementById('nav-wish-count');

                if (!grid) return;

                if (App.State.wishlist.length === 0) { 
                    grid.innerHTML = ''; 
                    if(empty) empty.style.display = 'block'; 
                    if(badge) badge.style.display = 'none'; 
                    return; 
                }

                if(empty) empty.style.display = 'none';
                if(badge) { 
                    badge.innerText = App.State.wishlist.length; 
                    badge.style.display = 'block'; 
                }

                grid.innerHTML = App.State.wishlist.map(i => `
                    <div class="col-6 col-md-4 col-lg-3">
                        <div class="product-card position-relative h-100 border">
                            <button class="btn btn-sm bg-white rounded-circle shadow-sm position-absolute" 
                                    style="top:10px; right:10px; z-index:5; width:30px; height:30px; padding:0;" 
                                    onclick="event.stopPropagation(); App.Wishlist.remove('${i.id}')">
                                <i class="bi bi-x-lg text-danger" style="font-size:12px;"></i>
                            </button>
                            <div class="img-box" onclick="App.QuickView.open('${i.id}')">
                                <img src="${i.image}" onerror="this.src='${IMG_FALLBACK}'"/>
                            </div>
                            <div class="p-3" onclick="App.QuickView.open('${i.id}')">
                                <div class="product-title">${App.UI.text(i.title)}</div>
                                <div class="text-primary fw-bold mt-2">${App.UI.price(i.price_MAD)}</div>
                                <button class="btn btn-sm btn-primary w-100 rounded-pill mt-3" 
                                        onclick="event.stopPropagation(); App.Cart.add('${i.id}')">
                                    Ajouter
                                </button>
                            </div>
                        </div>
                    </div>`).join('');
            }
        },

        Sync: {
            toSheet: (type, data) => {
                if (!App.State.user || type === 'viewed') return;
                const payload = { action: "syncUserData", data: { phone: App.State.user.phone, type: type, items: JSON.stringify(data.map(i => ({ id: i.id, qty: i.qty || 1 }))) } };
                fetch(API_URL, { method: 'POST', body: JSON.stringify(payload) }).catch(err => console.log("Sync error", err));
            }
        },

        Router: {
            go: (v) => {
                document.querySelectorAll('.module-section').forEach(s => { s.classList.remove('active'); s.style.setProperty('display', 'none', 'important'); });
                const target = document.getElementById(v + '-module');
                if(target) { target.style.setProperty('display', 'block', 'important'); setTimeout(() => target.classList.add('active'), 50); }
                window.scrollTo(0,0);
            }
        },

        Viewed: {
            add: (id) => {
                let viewed = JSON.parse(localStorage.getItem('se_viewed') || "[]");
                viewed = viewed.filter(vId => String(vId) !== String(id)); viewed.unshift(String(id)); viewed = viewed.slice(0, 12);
                localStorage.setItem('se_viewed', JSON.stringify(viewed)); localStorage.setItem('se_viewed_ts', Date.now().toString());
                if (App.State.user) fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: "logView", data: { userId: App.State.user.phone, productId: id } }) });
                App.Viewed.render();
            },
            render: () => {
                const ids = JSON.parse(localStorage.getItem('se_viewed') || "[]");
                if (ids.length === 0) return;
                const items = ids.map(id => App.State.catalog.find(p => String(p.id) === String(id))).filter(Boolean);
                const root = document.getElementById('recently-viewed-root'), section = document.getElementById('viewed-section');
                if (root && items.length > 0) { if(section) section.style.display = 'block'; root.innerHTML = items.map(i => App.UI.renderCard(i)).join(''); } 
                else if(section) section.style.display = 'none';
            }
        },

        ExitIntent: {
            hasShown: false,
            init: () => {
                if (localStorage.getItem('exit_shown')) return;
                document.addEventListener("mouseleave", (e) => { if (e.clientY < 0) App.ExitIntent.show(); });
                document.addEventListener("visibilitychange", () => { if (document.visibilityState === 'hidden') App.ExitIntent.show(); });
            },
            show: () => {
                if (App.ExitIntent.hasShown || App.State.cart.length === 0) return;
                const modal = document.getElementById('exit-intent');
                if (modal) { modal.style.display = 'flex'; App.ExitIntent.hasShown = true; localStorage.setItem('exit_shown', 'true'); if (navigator.vibrate) navigator.vibrate(20); }
            },
            applyDiscount: () => {
                App.State.exitDiscountApplied = true; App.Cart.calculateTotals();
                document.getElementById('exit-intent').style.display = 'none';
                App.UI.toast("Réduction de 5% appliquée ! 🏷️");
                if (document.getElementById('cart-module').style.display === 'none') App.Router.go('cart');
            }
        },

        SocialProof: {
            names: ["Youssef", "Amine", "Sarah", "Mehdi", "Layla", "Othmane", "Hamza", "Zineb", "Soufiane", "Anas", "Khadija", "Omar"],
            quartiers: ["Maarif", "Gauthier", "Bourgogne", "Anfa", "Oasis", "Ain Diab", "Belvédère"],
            init: () => {
                const checkReady = setInterval(() => { if (App.State.catalog && App.State.catalog.length > 0) { clearInterval(checkReady); setTimeout(App.SocialProof.show, 8000); } }, 1000);
            },
            show: () => {
                if (!App.State.catalog || App.State.catalog.length === 0) return;
                const name = App.SocialProof.names[Math.floor(Math.random() * App.SocialProof.names.length)];
                const quartier = App.SocialProof.quartiers[Math.floor(Math.random() * App.SocialProof.quartiers.length)];
                const product = App.State.catalog[Math.floor(Math.random() * App.State.catalog.length)];
                const time = Math.floor(Math.random() * 50) + 5;
                const toast = document.createElement('div');
                toast.style.cssText = `position: fixed; bottom: 25px; left: 20px; background: rgba(255, 255, 255, 0.9); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); padding: 12px 18px; border-radius: 22px; z-index: 11000; box-shadow: 0 15px 35px rgba(0,0,0,0.15); border: 1px solid rgba(255,255,255,0.3); display: flex; align-items: center; gap: 12px; transition: all 0.6s cubic-bezier(0.68, -0.55, 0.265, 1.55); transform: translateY(120px); opacity: 0; cursor: pointer; pointer-events: auto;`;
                toast.innerHTML = `<div style="width:42px; height:42px; background:var(--primary); border-radius:14px; display:flex; align-items:center; justify-content:center; color:white; flex-shrink:0;"><i class="bi bi-bag-heart-fill" style="font-size: 1.2rem;"></i></div><div style="line-height: 1.3; padding-right: 10px;"><div class="small fw-bold" style="font-size:0.75rem; color:#2d3436;">${name} à ${quartier}</div><div class="text-muted" style="font-size:0.65rem;">A commandé ${App.UI.text(product.title)}</div><div class="x-small text-primary fw-bold" style="font-size:0.6rem; margin-top:2px;">Il y a ${time} min</div></div>`;
                toast.onclick = () => { if (navigator.vibrate) navigator.vibrate(15); App.QuickView.open(product.id); toast.style.opacity = "0"; setTimeout(() => toast.remove(), 300); };
                document.body.appendChild(toast);
                setTimeout(() => { toast.style.transform = "translateY(0)"; toast.style.opacity = "1"; }, 100);
                setTimeout(() => { if (toast.parentNode) { toast.style.transform = "translateY(120px)"; toast.style.opacity = "0"; setTimeout(() => toast.remove(), 600); } }, 6000);
                setTimeout(App.SocialProof.show, (Math.floor(Math.random() * 50) + 30) * 1000);
            }
        },

		// --- PASTE THIS BETWEEN SocialProof AND PWA ---
        API: {
            init: () => {
                // 1. Check Store Status
                fetch(API_URL + '?action=checkStoreStatus').then(r=>r.json()).then(res => { 
                    if(res.status === 'success') { 
                        App.Config = {...App.Config, ...res.config}; 
                        if(App.Cart.renderZones) App.Cart.renderZones(res.config); 
                        if(!res.isOpen) { 
                            const badge = document.getElementById('store-float-badge'); 
                            if(badge) badge.classList.add('active'); 
                        } 
                    } 
                });

                // 2. Fetch Coupons
                fetch(API_URL + '?action=getCoupons').then(r=>r.json()).then(res => { 
                    if(res.status === 'success') App.State.coupons = res.data; 
                });

                // 3. Fetch Catalog (Loader stays ON until this finishes)
                fetch(API_URL + '?action=getCatalog').then(r=>r.json()).then(res => { 
                    if(res.status === 'success') { 
                        App.State.catalog = res.data; 

                        // Render Views
                        if(App.Catalog.renderFilters) App.Catalog.renderFilters();
                        if(App.Catalog.renderBatch) App.Catalog.renderBatch(true); 
                        if(App.Catalog.renderRecent) App.Catalog.renderRecent(); 

                        // 4. CHECK USER DATA before hiding loader
                        if(App.State.user) {
                            App.API.fetchUserData(); 
                        } else {
                            // No user? We are done. Hide loader.
                            App.UI.hideLoader();
                        }
                    } else {
                        App.UI.hideLoader(); // Hide if error
                    }
                }).catch(() => App.UI.hideLoader());

                if(App.I18n.fetch) App.I18n.fetch();
                if(App.Cart && App.API.checkout) App.Cart.checkout = App.API.checkout;
            },

            fetchUserData: (isPolling = false) => {
                const u = App.State.user;
                if (!u) { if(!isPolling) App.UI.hideLoader(); return; }

                // Keep loader visible if this is the initial load
                if (!isPolling) App.UI.showLoader();

                const cleanPhone = String(u.phone).replace(/\D/g, "");

                fetch(API_URL + '?action=getUserData&userId=' + encodeURIComponent(cleanPhone) + '&token=' + u.authToken)
                .then(r=>r.json()).then(res => {
                    // ALWAYS hide loader when fetch returns
                    if (!isPolling) App.UI.hideLoader();

                    if(res.status === 'success') {
                        // A. CART HYDRATION
                        if(res.cart && res.cart !== "[]" && App.State.catalog.length > 0) {
                             try {
                                 const rawCart = JSON.parse(res.cart);
                                 App.State.cart = rawCart.map(r => {
                                     const p = App.State.catalog.find(c => String(c.id) === String(r.id));
                                     return p ? { ...p, qty: r.qty } : null;
                                 }).filter(Boolean);
                                 App.Utils.save('se_cart', App.State.cart);
                             } catch(e) { console.log("Cart Sync Error", e); }
                        }

                        // B. WISHLIST FIX (Handle JSON vs CSV format)
                        if(res.wishlist && App.State.catalog.length > 0) {
                            let wishIds = [];
                            try {
                                // Backend often sends JSON array [{"id":"x"},...]
                                if(res.wishlist.trim().startsWith('[')) {
                                    const parsed = JSON.parse(res.wishlist);
                                    wishIds = parsed.map(x => x.id); 
                                } else {
                                    // Fallback to CSV
                                    wishIds = res.wishlist.split(',');
                                }
                            } catch(e) { wishIds = []; }

                            App.State.wishlist = wishIds.map(wid => 
                                App.State.catalog.find(c => String(c.id) === String(wid))
                            ).filter(Boolean);

                            App.Utils.save('se_wish', App.State.wishlist);
                        }

                        // C. OTHER DATA
                        if(res.currency) App.State.currency = res.currency;
                        if(res.orders) App.State.history = res.orders;
                        if(res.addresses) App.State.addresses = res.addresses;
                        if(res.profile && res.profile.points) {
                            App.State.user.points = res.profile.points;
                            App.Utils.save('se_user', App.State.user);
                        }

                        // D. RENDER UPDATES
                        if (!isPolling) {
                            if(App.Cart.render) App.Cart.render();
                            if(App.Wishlist.render) App.Wishlist.render();

                            const ptEl = document.getElementById('user-points-display');
                            if(ptEl) ptEl.innerText = App.State.user.points;
                            const cartPt = document.getElementById('cart-points-balance');
                            if(cartPt) cartPt.innerText = App.State.user.points;
                        }
                    }
                }).catch(e => { if(!isPolling) App.UI.hideLoader(); });
            },

            // Keep your existing push/checkout functions...
            push: (type) => { 
                const u = App.State.user; if(!u) return; 
                let action = 'syncUserData', data = { userId: u.phone, authToken: u.authToken }; 
                if(type === 'cart') { data.type = 'cart'; data.items = JSON.stringify(App.State.cart.map(i => ({ id: i.id, qty: i.qty }))); } 
                if(type === 'wish') { data.type = 'wishlist'; data.items = JSON.stringify(App.State.wishlist.map(i => ({ id: i.id }))); } 
                fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: action, data: data }) }); 
            },

            checkout: () => { 
                // ... (use your existing checkout code here) ...
                // If you need the checkout function provided again, let me know.
                // Assuming it's the same as previous step.
                 const total = App.Cart.calculateTotals();
                if (total === 0) return App.UI.toast("Panier vide", 'warning');
                if (total < 100) return App.UI.toast("Minimum de commande: 100 DH");

                const name = document.getElementById('chk-name').value.trim();
                const phone = document.getElementById('chk-phone').value.trim();
                const address = document.getElementById('chk-address').value.trim();

                if (!name || !phone || !address) return App.UI.toast("Veuillez remplir toutes les infos", 'warning');

                let msg = `*NOUVELLE COMMANDE* 🛒\n`;
                msg += `👤 *Client:* ${name}\n`;
                msg += `📞 *Tél:* ${phone}\n`;
                msg += `📍 *Adresse:* ${address}\n\n`;

                msg += `*ARTICLES:*\n`;
                App.State.cart.forEach(i => {
                    const title = (typeof i.title === 'object') ? (i.title.fr || i.title.en) : i.title;
                    msg += `▫️ ${i.qty}x ${title} (${i.price_MAD} DH)\n`;
                    if(i.variant_name) msg += `   └ _${i.variant_name}_\n`;
                });

                msg += `\n💰 *TOTAL:* ${total.toFixed(2)} DH`;
                if(App.Cart.activeCoupon) msg += `\n🏷️ *Code:* ${App.Cart.activeCoupon.code} (-${App.Cart.activeCoupon.val}%)`;

                const orderPayload = {
                    action: "placeOrder",
                    data: {
                        userId: App.State.user?.phone || "Guest",
                        name: name, phone: phone, address: address, total: total,
                        cart: App.State.cart.map(i => ({id:i.id, qty:i.qty, p:i.price_MAD, title: (typeof i.title === 'object' ? i.title.fr : i.title)})), 
                        note: App.Cart.deliveryMode,
                        coupon: App.Cart.activeCoupon ? App.Cart.activeCoupon.code : "",
                        pointsUsed: App.State.pointsRedeemed ? (App.State.userPoints || 0) : 0
                    }
                };

                const btn = document.querySelector('#cart-module .btn-primary');
                let oldTxt = "";
                if(btn) { oldTxt = btn.innerHTML; btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>'; }

                fetch(API_URL, { method: 'POST', body: JSON.stringify(orderPayload) })
                .then(r => r.json())
                .then(res => {
                    if(res.status === 'success') {
                        if(window.confetti) confetti({ particleCount: 200, spread: 80 });
                        setTimeout(() => {
                            const waLink = `https://wa.me/212661552233?text=${encodeURIComponent(msg)}`;
                            window.open(waLink, '_blank');
                            App.State.cart = []; App.Cart.save(); App.Router.go('home');
                            if(btn) { btn.disabled = false; btn.innerHTML = oldTxt; }
                        }, 1000);
                    } else {
                        App.UI.toast("Erreur: " + res.message, 'danger');
                        if(btn) { btn.disabled = false; btn.innerHTML = oldTxt; }
                    }
                })
                .catch(err => {
                    App.UI.toast("Erreur réseau", 'danger');
                    if(btn) { btn.disabled = false; btn.innerHTML = oldTxt; }
                });
            }
        },

        PWA: {
            deferredPrompt: null,
            init: () => {
                document.body.classList.add('has-promo'); // Ensure layout respects top bar

                window.addEventListener('beforeinstallprompt', (e) => {
                    e.preventDefault();
                    App.PWA.deferredPrompt = e;
                    console.log("PWA Ready");

                    // FORCE SHOW (Check removed for testing)
                    setTimeout(() => {
                        const toast = document.getElementById('install-prompt');
                        if(toast) toast.classList.add('active');
                    }, 3000);
                });

                window.addEventListener('appinstalled', () => {
                    document.getElementById('install-prompt').classList.remove('active');
                    App.UI.toast("Application installée ! 📲", "success");
                });
            },
            install: async () => {
                const promptEvent = App.PWA.deferredPrompt;
                if (!promptEvent) {
                    alert("Installation non disponible (déjà installé ou non supporté).");
                    return;
                }
                promptEvent.prompt();
                const { outcome } = await promptEvent.userChoice;
                App.PWA.deferredPrompt = null;
                document.getElementById('install-prompt').classList.remove('active');
            }
        },

        SEO: {
            init: () => {
                const script = document.getElementById('json-ld-store');
                // General Store Schema
                const data = {
                    "@context": "https://schema.org",
                    "@type": "Store",
                    "name": "Gorary Vape",
                    "image": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png",
                    "telephone": "0660109830", // Update with your number
                    "priceRange": "$$",
                    "address": {
                        "@type": "PostalAddress",
                        "addressLocality": "Casablanca",
                        "addressCountry": "MA"
                    }
                };
                script.textContent = JSON.stringify(data);
            },
            updateProduct: (item) => {
                // Updates Schema when opening a product (Good for Google)
                const script = document.getElementById('json-ld-store');
                const data = {
                    "@context": "https://schema.org",
                    "@type": "Product",
                    "name": App.UI.text(item.title),
                    "image": item.image || IMG_FALLBACK,
                    "description": "Vape product available at Gorary Vape Casablanca.",
                    "offers": {
                        "@type": "Offer",
                        "priceCurrency": "MAD",
                        "price": item.price_MAD,
                        "availability": item.stock > 0 ? "https://schema.org/InStock" : "https://schema.org/OutOfStock"
                    }
                };
                script.textContent = JSON.stringify(data);
            }
        }
    };

    document.addEventListener('DOMContentLoaded', () => {
        // 1. Show Loader IMMEDIATELY
        if(App.UI && App.UI.showLoader) App.UI.showLoader();

        // 2. Check Local User & Set Custom Text
        const localUser = JSON.parse(localStorage.getItem('se_user') || "null");
        if (localUser && document.getElementById('global-loader')) {
            // Update text to "Chargement de votre espace..."
            const textEl = document.getElementById('global-loader').querySelector('.text-muted');
            if(textEl) textEl.innerText = "Chargement de votre espace...";
        }

        // 3. Init PWA
        if(App.PWA) App.PWA.init();

        setTimeout(() => {
            try {
                if(App.AgeGate) App.AgeGate.init();
                if(App.ExitIntent) App.ExitIntent.init();
                if(App.Settings) App.Settings.init();
                if(App.API) App.API.init(); 

                // Load Local Data
                try {
                    App.State.cart = JSON.parse(localStorage.getItem('se_cart') || "[]");
                    App.State.wishlist = JSON.parse(localStorage.getItem('se_wishlist') || "[]");
                } catch(e) {}

                if(App.Catalog) {
                    App.Catalog.init(() => {
                        // --- CATALOG READY ---
                        if(App.Cart.render) App.Cart.render();
                        if(App.Viewed && App.Viewed.render) App.Viewed.render();
                        if(App.Wishlist && App.Wishlist.render) App.Wishlist.render();

                        if (localUser) {
                            if(App.Auth) App.Auth.restoreSession(localUser);
                            // Loader stays UP. API.fetchUserData will hide it when finished.
                            if(App.API) App.API.fetchUserData(); 
                        } else {
                            // Guest: We are done. Hide Loader.
                            if(App.UI) App.UI.hideLoader();
                        }
                    });
                } else {
                    if(App.UI) App.UI.hideLoader();
                }

                // Admin Trigger
                const pb = document.getElementById('admin-secret-trigger');
                if(pb) {
                    pb.addEventListener('click', (e) => { if(e.detail < 2) App.Router.go('profile'); });
                    pb.addEventListener('dblclick', () => { if(App.Admin) App.Admin.login(); });
                }

                if(App.SocialProof) App.SocialProof.init();
                if(App.SEO) App.SEO.init();

            } catch (e) {
                console.error("Critical App Load Error:", e);
                if(App.UI) App.UI.hideLoader();
            }
        }, 200);

        window.addEventListener('scroll', () => {
            if (window.scrollY > 10) document.body.classList.add('is-scrolled');
            else document.body.classList.remove('is-scrolled');
        });

        // Scroll Police
        setInterval(() => {
            const modal = document.getElementById('qvModal');
            const isModalOpen = modal && modal.classList.contains('show');
            if (!isModalOpen && (document.body.classList.contains('modal-open') || document.body.style.overflow === 'hidden')) {
                document.body.classList.remove('modal-open');
                document.body.style.overflow = '';
                document.body.style.paddingRight = '';
                const bd = document.querySelector('.modal-backdrop');
                if(bd) bd.remove();
            }
        }, 1500);
    });
